```html
<!DOCTYPE html>
<html lang="zh-CN">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=yes, viewport-fit=cover">
        <style>
            @import url('https://cdn.jsdelivr.net/npm/lxgw-wenkai-lite-webfont@1.1.0/style.css');

            :root {
                --paper-bg: #f4f1e8;
                --paper-dark: #e8e3d3;
                --ink-black: #1a1a1a;
                --ink-dark: #2c2c2c;
                --ink-gray: #5c5c5c;
                --ink-light: #8c8c8c;
                --accent-red: #9e2a2b;
                --accent-blue: #2a5c9e;
                --ink-fade: rgba(44, 44, 44, 0.08);
                --highlight-fade: rgba(255, 255, 255, 0.4);
                --panel-bg: rgba(255, 255, 255, 0.3);
                --text-glow: rgba(255, 255, 255, 0.5);
                --hover-bg: rgba(255, 255, 255, 0.4);
                --detail-bg-start: rgba(255, 255, 255, 0.5);
                --detail-bg-end: rgba(255, 255, 255, 0.2);
                --detail-arrow: #f7f5f0;
                --border-fade: rgba(44, 44, 44, 0.15);
                --border-light: rgba(44, 44, 44, 0.1);
                --empty-bg: rgba(44, 44, 44, 0.03);
                --tag-bg: rgba(44, 44, 44, 0.05);
                --shadow-outer: rgba(0, 0, 0, 0.1);
                --shadow-inner: rgba(140, 120, 100, 0.1);
            }

            :root[data-theme="dark"] {
                --paper-bg: #1E1E1E;
                --paper-dark: #1E1E1E;
                --ink-black: #CDC3B5;
                --ink-dark: #A99E91;
                --ink-gray: #9B8E7E;
                --ink-light: #7A7066;
                --accent-red: #E06C75;
                --accent-blue: #7AA2F7;
                --highlight-fade: transparent;
                --panel-bg: rgba(255, 255, 255, 0.05);
                --hover-bg: rgba(255, 255, 255, 0.08);
                --detail-bg-start: rgba(255, 255, 255, 0.06);
                --detail-bg-end: rgba(255, 255, 255, 0.03);
                --empty-bg: rgba(255, 255, 255, 0.03);
                --tag-bg: rgba(255, 255, 255, 0.1);
                --border-fade: rgba(255, 255, 255, 0.15);
                --border-light: rgba(255, 255, 255, 0.08);
                --text-glow: transparent;
                --detail-arrow: #2E2E2E;
                --shadow-inner: transparent;
                --shadow-outer: rgba(0, 0, 0, 0.4);
            }

            * {
                box-sizing: border-box;
                margin: 0;
                padding: 0;
            }

            body {
                font-family: "LXGW WenKai Lite", "LXGW WenKai", "LXGW WenKai Screen", "STZhongsong", "SimSun", serif;
                color: var(--ink-black);
                background: transparent;
                margin: 0;
                padding: 0;
                width: 100%;
            }

            .status-container {
                background: radial-gradient(circle at center, var(--paper-bg) 0%, var(--paper-dark) 150%);
                border: 1px solid var(--border-fade);
                border-radius: 2px;
                box-shadow: 0 4px 20px var(--shadow-outer), inset 0 0 40px var(--shadow-inner);
                width: calc(100% - 8px);
                margin: 0 auto;
                display: flex;
                flex-direction: column;
                position: relative;
            }

            .header-info {
                padding: 16px 16px 12px;
                flex-shrink: 0;
                background: linear-gradient(to bottom, var(--highlight-fade) 0%, transparent 100%);
                position: relative;
            }

            .header-info::after {
                content: '';
                position: absolute;
                bottom: 0;
                left: 10%;
                width: 80%;
                height: 1px;
                background: linear-gradient(90deg, transparent, var(--ink-gray), transparent);
            }

            @keyframes sealPulse {
                0% {
                    box-shadow: 0 0 0 0 rgba(158, 42, 43, 0.4);
                }

                70% {
                    box-shadow: 0 0 0 6px rgba(158, 42, 43, 0);
                }

                100% {
                    box-shadow: 0 0 0 0 rgba(158, 42, 43, 0);
                }
            }

            .ledger-btn {
                position: absolute;
                top: 12px;
                left: 16px;
                width: 26px;
                height: 26px;
                border-radius: 4px;
                border: 1px solid var(--accent-red);
                background: transparent;
                color: var(--accent-red);
                font-size: 14px;
                font-weight: 600;
                display: flex;
                align-items: center;
                justify-content: center;
                cursor: pointer;
                z-index: 10;
                transition: all 0.3s;
                font-family: inherit;
                outline: none;
                animation: sealPulse 3s infinite;
            }

            .ledger-btn:hover {
                background: rgba(158, 42, 43, 0.05);
                transform: scale(1.05);
            }

            .theme-btn {
                position: absolute;
                top: 12px;
                right: 16px;
                background: transparent;
                border: none;
                font-size: 18px;
                cursor: pointer;
                opacity: 0.6;
                transition: opacity 0.3s, transform 0.3s;
                z-index: 10;
                color: var(--ink-dark);
                outline: none;
            }

            .theme-btn:hover {
                opacity: 1;
                transform: scale(1.1);
            }

            .time-loc-grid {
                display: grid;
                grid-template-columns: 1fr auto 1fr;
                column-gap: 16px;
                row-gap: 6px;
                align-items: center;
                margin: 0 auto;
                width: fit-content;
                font-size: 21px;
                font-weight: 600;
                line-height: 1.2;
                letter-spacing: 2px;
                color: var(--ink-dark);
                text-shadow: 1px 1px 0 var(--text-glow);
            }

            .tl-left {
                text-align: right;
                justify-self: end;
            }

            .tl-center {
                color: var(--ink-light);
                font-weight: 400;
                font-size: 18px;
                user-select: none;
            }

            .tl-right {
                text-align: left;
                justify-self: start;
            }

            .wealth-standalone {
                margin-top: 12px;
                padding: 6px 8px;
                background: var(--panel-bg);
                border-radius: 4px;
                font-size: 16px;
                color: var(--ink-dark);
                border: 1px solid var(--border-light);
                box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.02);
                letter-spacing: 1px;
                display: flex;
                justify-content: center;
                align-items: center;
            }

            .wealth-line {
                display: flex;
                justify-content: center;
                align-items: center;
                white-space: nowrap;
            }

            .wealth-unit {
                white-space: nowrap;
            }

            .wealth-dot {
                margin: 0 4px;
            }

            .wealth-sep-main {
                margin: 0 6px;
            }

            .wealth-val {
                font-weight: 600;
                color: var(--ink-black);
            }

            .wealth-group {
                white-space: nowrap;
            }

            .tabs {
                display: flex;
                flex-shrink: 0;
                position: relative;
                flex-wrap: wrap;
            }

            .tabs::after {
                content: '';
                position: absolute;
                bottom: 0;
                left: 0;
                width: 100%;
                height: 2px;
                background: var(--ink-dark);
            }

            .tab-btn {
                flex: 1;
                min-width: 20%;
                padding: 14px 0;
                text-align: center;
                cursor: pointer;
                font-family: inherit;
                font-size: 17px;
                font-weight: 600;
                color: var(--ink-light);
                background: transparent;
                border: none;
                outline: none;
                transition: all 0.3s ease;
                letter-spacing: 1px;
                position: relative;
                z-index: 2;
            }

            .tab-btn.active {
                color: var(--ink-black);
                background: linear-gradient(to top, var(--ink-fade) 0%, transparent 100%);
            }

            .tab-btn.active::after {
                content: '';
                position: absolute;
                bottom: 0;
                left: 50%;
                transform: translateX(-50%);
                width: 40%;
                height: 3px;
                background: var(--accent-red);
                border-radius: 2px 2px 0 0;
            }

            .tab-btn:not(:last-child)::before {
                content: '';
                position: absolute;
                right: 0;
                top: 25%;
                height: 50%;
                width: 1px;
                background: linear-gradient(to bottom, transparent, var(--border-fade), transparent);
            }

            .content-area {
                padding: 20px 20px 24px;
                flex: 1 1 auto;
            }

            .page {
                display: none;
                animation: fadeIn 0.4s ease-out;
            }

            .page.active {
                display: block;
            }

            @keyframes fadeIn {
                from {
                    opacity: 0;
                    transform: translateY(6px);
                }

                to {
                    opacity: 1;
                    transform: translateY(0);
                }
            }

            .section-title {
                font-size: 19px;
                font-weight: 600;
                margin: 16px 0 12px;
                padding-left: 12px;
                position: relative;
                color: var(--ink-black);
                letter-spacing: 2px;
            }

            .section-title::before {
                content: '';
                position: absolute;
                left: 0;
                top: 50%;
                transform: translateY(-50%);
                width: 4px;
                height: 16px;
                background: var(--accent-red);
                border-radius: 1px;
            }

            .drawer {
                margin-bottom: 12px;
                border: 1px solid var(--border-fade);
                border-radius: 4px;
                background: linear-gradient(135deg, var(--detail-bg-start) 0%, var(--detail-bg-end) 100%);
                overflow: hidden;
            }

            .drawer-header {
                padding: 12px 16px 12px 12px;
                display: flex;
                justify-content: space-between;
                align-items: center;
                cursor: pointer;
                font-weight: 600;
                font-size: 17px;
                color: var(--ink-dark);
                transition: background 0.2s;
                position: relative;
            }

            .drawer-header::before {
                content: '';
                position: absolute;
                left: 0;
                top: 50%;
                transform: translateY(-50%);
                width: 4px;
                height: 16px;
                background: var(--accent-red);
                border-radius: 1px;
            }

            .drawer-header:hover {
                background: var(--hover-bg);
            }

            .drawer-count {
                font-size: 13px;
                color: var(--ink-gray);
                background: var(--tag-bg);
                padding: 1px 6px;
                border-radius: 4px;
                margin-left: 6px;
                font-weight: normal;
                font-family: monospace;
            }

            .drawer-icon {
                transition: transform 0.3s ease;
                color: var(--ink-gray);
                font-size: 14px;
            }

            .drawer.open .drawer-icon {
                transform: rotate(90deg);
            }

            .drawer-content {
                display: none;
                padding: 0 12px 0;
                border-top: 1px dashed var(--border-light);
            }

            .page>.drawer:last-child {
                margin-bottom: 0;
            }

            .item-list {
                list-style: none;
                margin-bottom: 12px;
            }

            .item-list li {
                font-size: 17px;
                line-height: 1.7;
                padding: 8px 4px;
                border-bottom: 1px dashed var(--border-fade);
                display: flex;
                flex-direction: column;
                color: var(--ink-dark);
                transition: background 0.2s;
            }

            .item-list li:last-child {
                border-bottom: none;
            }

            .item-list li:hover {
                background: var(--hover-bg);
            }

            .item-list li.empty-tip {
                display: block;
                text-align: center;
                border-bottom: none;
                color: var(--ink-light);
                padding: 16px;
                letter-spacing: 1px;
                background: linear-gradient(90deg, transparent, var(--empty-bg), transparent);
            }

            #secret-list li {
                flex-direction: row;
                justify-content: space-between;
                align-items: center;
            }

            .row-layout {
                display: flex;
                justify-content: space-between;
                align-items: center;
                width: 100%;
            }

            .row-layout.bottom-row {
                margin-top: 4px;
                align-items: flex-start;
            }

