                    '酉正': 18,
                    '戌初': 19,
                    '戌正': 20,
                    '亥初': 21,
                    '亥正': 22
                };
                const keMap = {
                    '一刻': 15,
                    '二刻': 30,
                    '三刻': 45
                };
                const m = str.match(/^([子丑寅卯辰巳午未申酉戌亥][正初])(一刻|二刻|三刻)?$/);
