                    $('#daoshu-cap-row').html(`当前境界上限：<b>${escapeHtml(cat.caps[currentRealm] || '未知')}</b>`).show();
                    let html = '';
                    cat.methods.forEach(m => {
                        const itemTag = m.item ? `<span class="ds-need">所需 ${escapeHtml(m.item)}</span>` : '';
                        html += `<li class="daoshu-skill" data-skill="${escapeHtml(m.name)}"><div class="ds-head"><span class="ds-name">${escapeHtml(m.name)}</span>${itemTag}</div><div class="ds-desc">${escapeHtml(m.detail)}</div></li>`;
                    });
                    $('#daoshu-skill-list').html(html);
                    return;
                }
                syncDaoshuRealm();
                renderDaoshuRealmSelect();
                $('#daoshu-cap-row').hide();
                const realmIdx = getRealmIndex(selectedRealm);
                const skills = cat.skills.filter(s => getRealmIndex(s.realm) === realmIdx);
                let html = '';
                if (!skills.length) {
                    html = '<li class="empty-tip">此境界尚无可用之术</li>';
                } else {
                    const realmUnlocked = getRealmIndex(currentRealm) >= getRealmIndex('合道境');
                    skills.forEach(s => {
                        if (s.passive) {
                            html += `<li class="daoshu-skill passive" data-passive="1"><div class="ds-head"><span class="ds-name">${escapeHtml(s.name)}</span><span class="ds-realm-tag">${escapeHtml(s.realm)}</span><span class="ds-passive-tag">被动</span></div><div class="ds-desc">${escapeHtml(s.desc)}</div></li>`;
                            return;
                        }
                        if (cat.itemBased) {
                            const count = getItemCount(s.name);
                            const disabled = count <= 0 && !realmUnlocked ? ' disabled' : '';
                            const countClass = count <= 0 ? ' ds-count zero' : '';
                            const unlockTag = (count <= 0 && realmUnlocked) ? '<span class="ds-unlock-tag">通天符生效</span>' : '';
                            html += `<li class="daoshu-skill${disabled}" data-skill="${escapeHtml(s.name)}"><div class="ds-head"><span class="ds-name">${escapeHtml(s.name)}</span><span class="ds-count${countClass}">x${escapeHtml(count)}</span>${unlockTag}</div><div class="ds-desc">${escapeHtml(s.desc)}</div><div class="ds-foot"><span class="ds-realm-tag">${escapeHtml(s.realm)}</span><button class="ds-make" data-make="${escapeHtml(s.name)}">制作</button></div></li>`;
                        } else {
                            html += `<li class="daoshu-skill" data-skill="${escapeHtml(s.name)}"><div class="ds-head"><span class="ds-name">${escapeHtml(s.name)}</span><span class="ds-realm-tag">${escapeHtml(s.realm)}</span></div><div class="ds-desc">${escapeHtml(s.desc)}</div></li>`;
                        }
                    });
                }
                $('#daoshu-skill-list').html(html);
            }

            function openDaoshuModal(type) {
                if (type) daoshuActiveType = type;
                syncDaoshuRealm();
                $('#daoshu-realm-label').text('当前境界：' + (currentRealm || '未知'));
                renderDaoshuTypeTabs();
                renderDaoshuSkills();
                $('#daoshu-modal').addClass('active');
            }

            function closeDaoshuModal() {
                $('#daoshu-modal').removeClass('active');
                $('#daoshu-confirm-modal').removeClass('active');
                $('#daoshu-target-panel').hide();
                $('#daoshu-target-error').hide();
                daoshuSelectedSkill = null;
                daoshuPending = null;
            }

            function showTargetPanel(type, skill) {
                daoshuSelectedSkill = skill;
                $('#daoshu-target-input').val('');
                $('#daoshu-matter-input').val('');
                $('#daoshu-target-error').hide();
                if (type === '占验') {
                    $('#daoshu-matter-wrap').show();
                    $('#daoshu-target-input').attr('placeholder', '占验何人，可留空');
                    $('#daoshu-target-title').text('对象（可选）');
                } else if (type === '丹鼎') {
                    $('#daoshu-matter-wrap').hide();
                    $('#daoshu-target-input').attr('placeholder', '何人服用…');
                    $('#daoshu-target-title').text('服用者');
                } else if (type === '符箓') {
                    $('#daoshu-matter-wrap').hide();
                    $('#daoshu-target-input').attr('placeholder', '贴于何人何物…');
                    $('#daoshu-target-title').text('使用对象');
                } else {
                    $('#daoshu-matter-wrap').hide();
                    $('#daoshu-target-input').attr('placeholder', '对何人施展…');
                    $('#daoshu-target-title').text('施展对象');
                }
                $('#daoshu-target-panel').show();
                setTimeout(() => {
                    $('#daoshu-target-input').focus();
                }, 50);
            }

            function renderConfirm() {
                const p = daoshuPending;
                if (!p) return;
                let html = '';
                if (p.mode === 'make') {
                    html = `制作「<span class="cs-skill">${escapeHtml(p.skill)}</span>」`;
                } else if (p.type === '占验') {
                    html = `使用「<span class="cs-skill">${escapeHtml(p.skill)}</span>」${p.target ? `为「<span class="cs-target">${escapeHtml(p.target)}</span>」` : ''}占验「<span class="cs-matter">${escapeHtml(p.matter)}</span>」`;
                } else if (p.type === '丹鼎') {
                    html = `让「<span class="cs-target">${escapeHtml(p.target)}</span>」服用「<span class="cs-skill">${escapeHtml(p.skill)}</span>」`;
                } else {
                    const verb = p.type === '幻术' ? '施展' : '使用';
                    html = `对「<span class="cs-target">${escapeHtml(p.target)}</span>」${verb}「<span class="cs-skill">${escapeHtml(p.skill)}</span>」`;
                }
                $('#confirm-summary').html(html);
            }

            function buildUseText() {
                const p = daoshuPending;
                if (!p) return '';
                if (p.mode === 'make') return '制作' + p.skill;
                const t = (p.target || '').trim();
                const m = (p.matter || '').trim();
                switch (p.type) {
                    case '符箓':
                        return '对' + t + '使用' + p.skill;
                    case '丹鼎':
                        return '让' + t + '服用' + p.skill;
                    case '幻术':
                        return '对' + t + '施展' + p.skill;
                    case '占验':
                        return t ? '使用' + p.skill + '为' + t + '占验' + m : '使用' + p.skill + '占验' + m;
                }
                return '';
            }

            function submitDaoshuTarget() {
                const target = ($('#daoshu-target-input').val() || '').trim();
                const matter = ($('#daoshu-matter-input').val() || '').trim();
                if (daoshuActiveType === '占验') {
                    if (!matter) {
                        $('#daoshu-target-error').text('请填写所占何事。').show();
                        return;
                    }
                    daoshuPending = {
                        mode: 'use',
                        type: daoshuActiveType,
                        skill: daoshuSelectedSkill,
                        target: target,
                        matter: matter
                    };
                } else {
                    if (!target) {
                        $('#daoshu-target-error').text('请先填入对象。').show();
                        return;
                    }
                    daoshuPending = {
                        mode: 'use',
                        type: daoshuActiveType,
                        skill: daoshuSelectedSkill,
                        target: target,
                        matter: ''
                    };
                }
                renderConfirm();
                $('#daoshu-confirm-modal').addClass('active');
            }
            async function appendToUserInput(text) {
                try {
                    const doc = window.parent.document;
                    const ta = doc.getElementById('send_textarea');
                    if (ta) {
                        const cur = ta.value || '';
                        ta.value = cur ? cur + '\n' + text : text;
                        ta.dispatchEvent(new Event('input', {
                            bubbles: true
                        }));
                        try {
                            ta.focus();
                        } catch (e) {}
                        return true;
                    }
                } catch (e) {}
                try {
                    await triggerSlash('/input' + text);
                    return true;
                } catch (e) {}
                return false;
            }
            async function confirmDaoshuUse() {
                const text = buildUseText();
                if (!text) return;
                const ok = await appendToUserInput(text);
                closeDaoshuModal();
                if (!ok) {
                    try {
                        toastr.warning('未能写入输入栏，请手动输入：' + text);
                    } catch (e) {
                        window.alert('未能写入输入栏，请手动输入：' + text);
                    }
                }
            }
            async function removeFromVariable(pathSegments) {
                let success = true;
                try {
                    const latestData = Mvu.getMvuData({
                        type: 'message',
                        message_id: 'latest'
                    });
                    if (latestData && _.get(latestData, pathSegments) !== undefined) {
                        _.unset(latestData, pathSegments);
                        await Mvu.replaceMvuData(latestData, {
                            type: 'message',
                            message_id: 'latest'
                        });
                    }
                } catch (error) {
                    success = false;
                }
                try {
                    const currentMsgId = getCurrentMessageId();
                    if (typeof currentMsgId === 'number') {
                        const currentData = Mvu.getMvuData({
                            type: 'message',
                            message_id: currentMsgId
                        });
                        if (currentData && _.get(currentData, pathSegments) !== undefined) {
                            _.unset(currentData, pathSegments);
                            await Mvu.replaceMvuData(currentData, {
                                type: 'message',
                                message_id: currentMsgId
                            });
                        }
                    }
                } catch (error) {}
                return success;
            }

            function populateCharacterData() {
                const all_vars = fbCurrentVars();
