                const month = world['月份'] ? `${numToChinese(world['月份'])}月` : '';
                const day = world['日期'] ? (world['日期'] < 11 ? '初' + numToChinese(world['日期']) : numToChinese(world['日期'])) : '';
                const festival = world['节气或节日'] && world['节气或节日'] !== '无' ? ` [${world['节气或节日']}]` : '';
                const hour = _.get(world, '小时', 0);
