            }

            function saveTheme(theme) {
                try {
                    localStorage.setItem('mvu-status-theme', theme);
                } catch (e) {}
            }

            function initTheme() {
                const savedTheme = getSavedTheme();
                if (savedTheme === 'dark') {
                    document.documentElement.setAttribute('data-theme', 'dark');
