            var fbKey = 'dg_floorbar_folded';
            var fbFloorIds = [];
            var fbIndex = -1;
            var fbOwnId = null;
            var fbLatestId = null;

            function fbOwnMessageId() {
                try {
                    if (typeof getMessageId === 'function' && typeof getIframeName === 'function') {
                        const n = getMessageId(getIframeName());
                        if (typeof n === 'number' && n >= 0) {
                            return n;
                        }
                    }
                } catch (e) {}
                try {
                    const n = getCurrentMessageId();
                    if (typeof n === 'number' && n >= 0) {
                        return n;
                    }
                } catch (e) {}
                return null;
            }

            function fbCollectFloors() {
                try {
                    const list = getChatMessages('0-' + getLastMessageId(), {
                        role: 'assistant',
                        hide_state: 'all'
                    });
                    return list.filter(function(m) { return m.is_hidden !== true; })
                        .map(function(m) { return m.message_id; })
                        .filter(function(id) { return typeof id === 'number'; })
                        .sort(function(a, b) { return a - b; });
                } catch (e) {
                    return [];
                }
            }

            function fbRefreshFloors() {
                fbFloorIds = fbCollectFloors();
                fbLatestId = fbFloorIds.length ? fbFloorIds[fbFloorIds.length - 1] : fbOwnId;
            }

            function fbHideSelf() {
                try {
                    document.documentElement.style.display = 'none';
                } catch (e) {}
                try {
                    if (window.frameElement) {
                        window.frameElement.style.display = 'none';
                        window.frameElement.style.height = '0px';
                    }
                } catch (e) {}
            }

            function fbViewingLatest() {
                if (!fbFloorIds.length || fbIndex < 0) {
                    return true;
                }
                return fbFloorIds[fbIndex] === fbLatestId;
            }

            function fbCurrentVars() {
                if (fbViewingLatest()) {
                    return getAllVariables();
                }
                try {
                    const d = Mvu.getMvuData({ type: 'message', message_id: fbFloorIds[fbIndex] });
                    const sd = _.get(d, 'stat_data', null);
                    if (sd && Object.keys(sd).length) {
                        return d;
                    }
                } catch (e) {}
                return getAllVariables();
            }

            function fbReadFold() {
                try {
                    return (window.parent.localStorage.getItem(fbKey) || '1') === '1';
                } catch (e) {
                    try {
                        return (localStorage.getItem(fbKey) || '1') === '1';
                    } catch (e2) {
                        return true;
                    }
                }
            }

            function fbSaveFold(v) {
                try {
                    window.parent.localStorage.setItem(fbKey, v ? '1' : '0');
                } catch (e) {
                    try {
                        localStorage.setItem(fbKey, v ? '1' : '0');
                    } catch (e2) {}
                }
            }

            function fbRenderBar() {
                const id = (fbIndex >= 0 && fbFloorIds[fbIndex] !== undefined) ? fbFloorIds[fbIndex] : fbOwnId;
                $('#fb-num').text(id === null || id === undefined ? '?' : id);
                $('#fb-num').toggleClass('fb-num-old', !fbViewingLatest());
                const atFirst = fbIndex <= 0;
                const atLast = fbIndex < 0 || fbIndex >= fbFloorIds.length - 1;
                $('#fb-first').prop('disabled', atFirst);
                $('#fb-prev').prop('disabled', atFirst);
                $('#fb-next').prop('disabled', atLast);
                $('#fb-last').prop('disabled', atLast);
            }

            function fbGoTo(i) {
                if (!fbFloorIds.length) {
                    return;
                }
                i = Math.max(0, Math.min(fbFloorIds.length - 1, i));
                if (i === fbIndex) {
                    return;
                }
                fbIndex = i;
                fbRenderBar();
                populateCharacterData();
            }

            function fbSetup() {
                const $c = $('.status-container');
                $c.toggleClass('collapsed', fbReadFold());
                $('#fb-center').on('click', function() {
                    const collapsed = !$c.hasClass('collapsed');
                    $c.toggleClass('collapsed', collapsed);
                    fbSaveFold(collapsed);
                });
                $('#fb-first').on('click', function() { fbGoTo(0); });
                $('#fb-prev').on('click', function() { fbGoTo(fbIndex - 1); });
                $('#fb-next').on('click', function() { fbGoTo(fbIndex + 1); });
                $('#fb-last').on('click', function() { fbGoTo(fbFloorIds.length - 1); });
                fbRenderBar();
            }

            $(errorCatched(init));

        </script>
