        function removeTags(text, startTag, endTag) {
            var pairRe = new RegExp(startTag + '(?:(?!' + startTag + ')[\\s\\S])*?' + endTag, 'g');
            return text.replace(pairRe, '');
        }

        function extractContent(messageText) {
            var cleanText = removeTags(messageText, '<think' + '>', '</think' + '>');
            cleanText = removeTags(cleanText, '<thinking' + '>', '</thinking' + '>');
            cleanText = removeTags(cleanText, '<UpdateVariable>', '</UpdateVariable>');

            var tagStart = '<sgq-cshx>';
            var tagEnd = '</sgq-cshx>';
            var blockRe = new RegExp(tagStart + '(?:(?!' + tagStart + ')[\\s\\S])*?' + tagEnd, 'g');
            var last = null;
            var hit = blockRe.exec(cleanText);
            while (hit !== null) {
                last = hit[0];
                hit = blockRe.exec(cleanText);
            }
            if (last === null) {
                return "";
            }
            return last.substring(tagStart.length, last.length - tagEnd.length).trim();
        }

        function renderPage(text) {
            if (!text) {
                document.getElementById('content').innerHTML = '<div class="loading">暂无形迹</div>';
