            paragraphs.forEach(function(p, i) {
                var trimmed = p.trim();
                if (trimmed) {
                    html += '<p style="animation-delay:' + (0.15 + i * 0.08) + 's">' + trimmed + '</p>';
                }
            });

            document.getElementById('content').innerHTML = html;
