                var messageText = getMessageData();
                if (!messageText) {
                    document.getElementById('content').innerHTML = '<div class="loading">文卷难寻</div>';
                    return;
                }
                var text = extractContent(messageText);
                renderPage(text);
            } catch (error) {
                document.getElementById('content').innerHTML = '<div class="loading">展卷失败</div>';
            }
        }

