            var cleanText = removeThinkTags(messageText, '<think' + '>', '</think' + '>');
            cleanText = removeThinkTags(cleanText, '<thinking' + '>', '</thinking' + '>');

            var tagStart = '<sgq-options>';
            var tagEnd = '</sgq-options>';
            var lastStartIndex = cleanText.lastIndexOf(tagStart);

            if (lastStartIndex === -1) {
                return options;
            }

            var contentStart = lastStartIndex + tagStart.length;
            var endIndex = cleanText.indexOf(tagEnd, contentStart);
            var content = "";

            if (endIndex !== -1) {
                content = cleanText.substring(contentStart, endIndex).trim();
            } else {
                content = cleanText.substring(contentStart).trim();
            }

            var lines = content.split('\n');
            var titles = ['其一', '其二', '其三', '其四'];
            var index = 0;

            lines.forEach(function(line) {
                line = line.trim();
                if (line.startsWith('>')) {
                    var desc = line.substring(1).trim();
                    if (desc.startsWith('[') && desc.endsWith(']')) {
                        desc = desc.substring(1, desc.length - 1);
                    }
                    if (desc.length > 0) {
                        options.push({
                            title: index < titles.length ? titles[index] : '其' + (index + 1),
                            desc: desc
                        });
                        index++;
                    }
                }
            });

            return options;
        }

        function renderPage(options) {
            var contentDiv = document.getElementById('content');

            if (options.length === 0) {
                contentDiv.innerHTML = '<div class="loading">未能识破迷局。</div>';
                return;
            }

            var container = document.createElement('div');
            container.className = 'options-container';

            options.forEach(function(opt) {
                var card = document.createElement('div');
                card.className = 'option-card';

                var titleDiv = document.createElement('div');
                titleDiv.className = 'option-title';
                titleDiv.textContent = opt.title || '';

                var descDiv = document.createElement('div');
                descDiv.className = 'option-desc';
                descDiv.textContent = opt.desc || '';

                card.appendChild(titleDiv);
                card.appendChild(descDiv);

                card.addEventListener('click', function() {
                    var text = opt.desc || '';
                    var pDoc = window.parent ? window.parent.document : null;
                    if (pDoc) {
                        var textarea = pDoc.getElementById('send_textarea');
                        if (textarea) {
                            textarea.value = text;
                            textarea.dispatchEvent(new Event('input', { bubbles: true }));
                            try { textarea.focus(); } catch (e) {}
                        }
                    }
                });

                container.appendChild(card);
            });

            contentDiv.innerHTML = '';
            contentDiv.appendChild(container);
        }

        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) {
                    document.getElementById('content').innerHTML = '<div class="loading">未能获取卷宗...</div>';
                    return;
                }
                var options = parseData(messageText);
                renderPage(options);
            } catch (error) {
                document.getElementById('content').innerHTML = '<div class="loading">迷津难渡：' + error.message + '</div>';
            }
        }

        $(function() { init(); });
    </script>
</body>
</html>
