<body>
    <div class="csjs-wrap" id="csjsBox">
        <div class="csjs-head">
            <div class="rule-line"></div>
            <div class="rule-line"></div>
            <div class="csjs-title" id="csjsTitle">差事结算</div>
            <div class="rule-line"></div>
            <div class="rule-line"></div>
        </div>
        <div id="csjsBody">
            <div class="csjs-empty">正在核销功过</div>
        </div>
    </div>

    <script>
        function csjsGetMessage() {
            var list = getChatMessages(getCurrentMessageId());
            if (!list || list.length === 0) {
                return null;
            }
            return list[0].message;
        }

        function csjsStrip(text, openTag, closeTag) {
            var pairRe = new RegExp(openTag + '(?:(?!' + openTag + ')[\\s\\S])*?' + closeTag, 'g');
            return text.replace(pairRe, '');
        }

        function csjsExtract(messageText) {
            var clean = csjsStrip(messageText, '<think' + '>', '</think' + '>');
            clean = csjsStrip(clean, '<thinking' + '>', '</thinking' + '>');
            clean = csjsStrip(clean, '<UpdateVariable>', '</UpdateVariable>');

            var open = '<sgq-csjs>';
            var close = '</sgq-csjs>';
            var blockRe = new RegExp(open + '(?:(?!' + open + ')[\\s\\S])*?' + close, 'g');
            var last = null;
            var hit = blockRe.exec(clean);
            while (hit !== null) {
                last = hit[0];
                hit = blockRe.exec(clean);
            }
            if (last === null) {
                return null;
            }
            return last.substring(open.length, last.length - close.length).trim();
        }

        function csjsParse(text) {
            var lines = text.split(/\r?\n/);
            var list = [];
            var cur = null;
            for (var i = 0; i < lines.length; i++) {
                var t = lines[i].trim();
                if (!t) {
                    continue;
                }
                var isItem = /^[-*]\s*/.test(t);
                var body = (isItem ? t.replace(/^[-*]\s*/, '') : t).replace(/\*/g, '').trim();
                if (!body) {
                    continue;
                }
                if (!isItem && /[:：]\s*$/.test(body)) {
                    if (cur) {
                        list.push(cur);
                    }
                    cur = {
                        name: body.replace(/[:：]\s*$/, '').replace(/^\$/, '').trim(),
                        rate: '',
                        result: '',
                        remark: ''
                    };
                    continue;
                }
                var m = body.match(/^(评价|成果|评语)[:：]\s*(.*)$/);
                if (m) {
                    if (!cur) {
                        cur = { name: '', rate: '', result: '', remark: '' };
                    }
                    var v = m[2].trim();
                    if (m[1] === '评价') {
                        cur.rate = v;
                    } else if (m[1] === '成果') {
                        cur.result = v;
                    } else {
                        cur.remark = cur.remark ? cur.remark + ' ' + v : v;
                    }
                    continue;
                }
                if (!cur) {
                    cur = { name: body.replace(/^\$/, '').trim(), rate: '', result: '', remark: '' };
                    continue;
                }
                if (cur.remark) {
                    cur.remark += ' ' + body;
                } else if (cur.result) {
                    cur.result += '；' + body;
                } else {
                    cur.name += body;
                }
            }
            if (cur) {
                list.push(cur);
            }
            return list;
        }

        function csjsEscape(s) {
            return String(s)
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;');
        }

        function csjsRateClass(rate) {
            if (rate.indexOf('出色') !== -1) { return 'r1'; }
            if (rate.indexOf('妥当') !== -1) { return 'r2'; }
            if (rate.indexOf('平平') !== -1) { return 'r3'; }
            if (rate.indexOf('差池') !== -1) { return 'r4'; }
            if (rate.indexOf('不堪') !== -1) { return 'r5'; }
            return 'r0';
        }

        function csjsRender(list) {
            var html = '';
            for (var i = 0; i < list.length; i++) {
                var it = list[i];
                html += '<div class="csjs-card">';
                html += '<div class="csjs-row">';
                html += '<div class="csjs-name">' + csjsEscape(it.name || '无名差事') + '</div>';
                html += '<div class="csjs-stamp ' + csjsRateClass(it.rate) + '">' + csjsEscape(it.rate || '未评') + '</div>';
                html += '</div>';
                if (it.remark) {
                    html += '<div class="csjs-cols">';
                    html += '<div class="csjs-col"><div class="csjs-label">成果</div><div class="csjs-text">' + csjsEscape(it.result || '无') + '</div></div>';
                    html += '<div class="csjs-col"><div class="csjs-label">评语</div><div class="csjs-remark">' + csjsEscape(it.remark) + '</div></div>';
                    html += '</div>';
                } else {
                    html += '<div class="csjs-label">成果</div><div class="csjs-text">' + csjsEscape(it.result || '无') + '</div>';
                }
                html += '</div>';
            }
            return html;
        }

        function csjsShowNone() {
            var box = document.getElementById('csjsBox');
            if (box) {
                box.className = 'csjs-wrap csjs-none';
            }
            var title = document.getElementById('csjsTitle');
            if (title) {
                title.textContent = '本轮无差事办结';
            }
        }

        function csjsInit() {
            var box = document.getElementById('csjsBox');
            if (box) {
                box.className = 'csjs-wrap';
            }
            var title = document.getElementById('csjsTitle');
            if (title) {
                title.textContent = '差事结算';
            }
            try {
                var messageText = csjsGetMessage();
                if (!messageText) {
                    csjsShowNone();
                    return;
                }
                var text = csjsExtract(messageText);
                if (text === null) {
                    csjsShowNone();
                    return;
                }
                if (!text || text === '无') {
                    csjsShowNone();
                    return;
                }
                var list = csjsParse(text);
                if (!list.length) {
                    csjsShowNone();
                    return;
                }
                document.getElementById('csjsBody').innerHTML = csjsRender(list);
            } catch (error) {
                csjsShowNone();
            }
        }

        $(function() { csjsInit(); });
    </script>
</body>
</html>
