        .enter-photo {
            position: absolute;
            inset: 0;
            background-image: var(--enter-photo);
            background-size: cover;
            background-position: center 40%;
            transform-origin: 64% 56%;
            animation: enterDrift 30s ease-in-out infinite alternate;
            transition: transform .7s cubic-bezier(.4,0,.2,1), filter .7s ease;
            will-change: transform;
        }
        @keyframes enterDrift {
            from { transform: scale(1.03); }
            to   { transform: scale(1.12); }
        }
        .enter-scrim {
            position: absolute;
            inset: 0;
            background:
                radial-gradient(120% 80% at 62% 36%, rgba(24,11,8,0.04) 0%, rgba(20,9,7,0.30) 70%, rgba(14,6,4,0.70) 100%),
                linear-gradient(180deg, rgba(18,8,6,0.52) 0%, rgba(18,8,6,0.22) 20%, rgba(18,8,6,0.58) 45%, rgba(18,8,6,0.28) 68%, rgba(12,5,3,0.86) 100%);
        }
        .enter-petals {
            --fall: 1260px;
            position: absolute;
            inset: 0;
            overflow: hidden;
            pointer-events: none;
            transition: opacity .5s ease;
        }
        .petal {
            position: absolute;
            top: -8%;
            width: var(--sz);
            height: var(--sz);
            opacity: var(--op);
            animation: petalFall var(--dur) linear infinite;
            animation-delay: var(--del);
            will-change: transform;
        }
        .petal i {
            display: block;
            width: 100%;
            height: 100%;
            border-radius: 100% 0 100% 0;
            background: linear-gradient(140deg, #FCF1EA 0%, #EFC9BD 46%, #C97F6E 100%);
            animation: petalTurn calc(var(--dur) / 4.5) ease-in-out infinite alternate;
        }
        .petal.near i { filter: blur(var(--bl)); }
        @keyframes petalFall {
            from { transform: translate3d(0, 0, 0); }
            to   { transform: translate3d(var(--sw), var(--fall), 0); }
        }
        @keyframes petalTurn {
            from { transform: rotate(-34deg) scaleX(1); }
            to   { transform: rotate(44deg) scaleX(0.34); }
        }
        .enter-body {
            position: absolute;
            inset: 0;
