        function startEditor(mode) {
            editorMode = mode;
            if (mode === 'free') {
                $('#editorTitle').text('简册速成');
                $('#page-editor').removeClass('mode-full').addClass('mode-free');
            } else {
                $('#editorTitle').text('详录履籍');
                $('#page-editor').removeClass('mode-free').addClass('mode-full');
            }
            if (currentEditorStep === 2) {
                switchEditorStep(1);
            }
            initTalentSection();
            togglePage('page-editor');
        }

        function togglePage(pageId) {
            document.body.classList.toggle('dg-splash', pageId === 'page-enter' || pageId === 'page-menu');
            $('.page').removeClass('active');
            const page = $('#' + pageId);
            page.addClass('active');
            $('.btn-select-start').hide();
            try {
                window.scrollTo({top: 0, behavior: 'smooth'});
            } catch (e) {
                window.scrollTo(0, 0);
            }

            page.find('.mode-card, .start-card').each(function(i) {
                const card = $(this);
                card.css({opacity: 0, transform: 'translateY(12px)'});
                setTimeout(function() {
                    card.css({opacity: 1, transform: 'translateY(0)', transition: 'all 0.4s cubic-bezier(0.16,1,0.3,1)'});
                }, 60 * i + 100);
            });

            if (pageId === 'page-editor') {
                if (currentEditorStep === 2) {
                    switchEditorStep(1);
                }
            }

        }

        function switchEditorStep(step) {
            currentEditorStep = step;
            $('#editorPage1, #editorPage2').removeClass('active').addClass('hidden');
            $('#editorPage' + step).removeClass('hidden').addClass('active');

            $('.editor-step').removeClass('active completed');
            $('.editor-step[data-step="1"]').addClass(step >= 1 ? 'active' : '');
            if (step === 2) {
                $('.editor-step[data-step="1"]').addClass('completed').removeClass('active');
                $('.editor-step[data-step="2"]').addClass('active');
            }

            $('#editorProgress').toggleClass('step2', step === 2);
            if (step === 2 && genderCode() !== lastTalentGender) {
                initTalentSection();
            }
