            if (g === '女') return 'f';
            if (g === '扶她（二形）') return 'h';
            return '';
        }

        function rollTalentCards(keepLocked) {
            const kept = keepLocked ? talentCards.filter(function(c) { return c.locked || talentSelected.some(function(t) { return t.name === c.talent.name; }); }) : [];
            const exclude = {};
            kept.forEach(function(c) { exclude[c.talent.name] = true; });
            const cards = kept.slice();
            const g = genderCode();
            while (cards.length < 5) {
                const level = pickTalentLevel();
                const candidates = talentPool.filter(function(t) { return t.lv === level && (!t.g || t.g === g) && !exclude[t.name]; });
                if (candidates.length === 0) continue;
                const talent = candidates[Math.floor(Math.random() * candidates.length)];
                exclude[talent.name] = true;
                cards.push({ talent: talent, locked: false });
            }
            talentCards = cards;
            lastTalentGender = g;
            renderTalentCards();
        }

        function renderTalentCards() {
            let html = '';
            talentCards.forEach(function(card, idx) {
                const level = TALENT_LEVELS[card.talent.lv];
                const isSelected = talentSelected.some(function(t) { return t.name === card.talent.name; });
                html += '<div class="talent-card lv-' + card.talent.lv + (isSelected ? ' selected' : '') + (card.locked ? ' locked' : '') + '" onclick="toggleTalentSelect(' + idx + ')">';
                html += '<div class="talent-level">' + level.label + '</div>';
                html += '<div class="talent-name">' + card.talent.name + '</div>';
                html += '<div class="talent-desc">' + card.talent.desc + '</div>';
                if (isSelected) html += '<div class="talent-pick-mark">已择</div>';
                html += '<div class="talent-lock' + (card.locked ? ' on' : '') + '" onclick="event.stopPropagation();toggleTalentLock(' + idx + ')">' + (card.locked ? '已锁' : '锁') + '</div>';
                html += '</div>';
            });
            $('.talent-cards').html(html);
        }

        function toggleTalentSelect(idx) {
            const card = talentCards[idx];
            if (!card) return;
            const pos = talentSelected.findIndex(function(t) { return t.name === card.talent.name; });
            if (pos !== -1) {
                talentSelected.splice(pos, 1);
            } else {
                if (talentSelected.length >= 5) { showAlert('提示', '至多择取五项天赋！'); return; }
                talentSelected.push(card.talent);
            }
            renderTalentCards();
        }

        function toggleTalentLock(idx) {
            const card = talentCards[idx];
            if (!card) return;
            if (card.locked) {
                card.locked = false;
            } else {
                const lockedCount = talentCards.filter(function(c) { return c.locked; }).length;
                if (lockedCount >= 3) { showAlert('提示', '至多锁住三张天赋卡！'); return; }
                card.locked = true;
            }
            renderTalentCards();
        }

        function refreshTalentCards() {
            rollTalentCards(true);
        }

        function initTalentSection() {
