        function renderImmersiveQuestion() {
            const q = immersiveQuestions[currentImIndex];
            let preTextStr = "";
            if (currentImIndex > 0) {
                let prevIndex = currentImIndex - 1;
                while (prevIndex >= 0 && immersiveQuestions[prevIndex].condition && !immersiveQuestions[prevIndex].condition()) {
                    prevIndex--;
                }
                if (prevIndex >= 0) {
                    const prevQ = immersiveQuestions[prevIndex];
                    if (prevQ.getDynamicNextPre) {
                        preTextStr = prevQ.getDynamicNextPre(imAnswers[prevQ.id]);
                    } else if (prevQ.type === 'buttons') {
                        const opts = prevQ.getDynamicOptions ? prevQ.getDynamicOptions() : prevQ.options;
                        const prevOpt = opts.find(function(o) { return o.value === imAnswers[prevQ.id]; });
                        if (prevOpt && prevOpt.nextPre) preTextStr = prevOpt.nextPre;
                    } else {
                        preTextStr = prevQ.nextPre || "";
                    }
                }
            }
            $('#im-pretext').text(preTextStr);

            const qText = typeof q.question === 'function' ? q.question() : q.question;
            $('#im-question').text(qText);

            const optsContainer = $('#im-options');
            optsContainer.empty();

            if (q.type === 'buttons') {
                const options = q.getDynamicOptions ? q.getDynamicOptions() : q.options;
                options.forEach(function(opt) {
                    const isSelected = imAnswers[q.id] === opt.value;
                    const optDiv = $('<div class="immersive-option ' + (isSelected ? 'selected' : '') + '">' + opt.label + '</div>');
                    optDiv.click(function() {
                        imAnswers[q.id] = opt.value;
                        nextImmersive();
                    });
                    optsContainer.append(optDiv);
                });
            } else if (q.type === 'multiselect') {
                const options = q.getDynamicOptions ? q.getDynamicOptions() : q.options;
                if (!imAnswers[q.id]) imAnswers[q.id] = [];

                options.forEach(function(opt) {
                    const isSelected = imAnswers[q.id].indexOf(opt.value) > -1;
                    const optDiv = $('<div class="immersive-option multiselect ' + (isSelected ? 'selected' : '') + '">' + opt.label + '</div>');
                    optDiv.click(function() {
                        if (opt.exclusive) {
                            imAnswers[q.id] = [opt.value];
                        } else {
                            const exclusiveOpt = options.find(function(o) { return o.exclusive; });
                            if (exclusiveOpt) {
                                imAnswers[q.id] = imAnswers[q.id].filter(function(v) { return v !== exclusiveOpt.value; });
                            }
                            const idx = imAnswers[q.id].indexOf(opt.value);
                            if (idx > -1) {
                                imAnswers[q.id].splice(idx, 1);
                            } else {
                                imAnswers[q.id].push(opt.value);
                            }
                        }
                        renderImmersiveQuestion();
                    });
                    optsContainer.append(optDiv);
                });

                const confirmBtn = $('<button class="dg-btn-submit" style="margin-top:15px;padding:14px;font-size:20px;">确认选择</button>');
                confirmBtn.prop('disabled', imAnswers[q.id].length === 0);
                confirmBtn.click(function() {
                    if (imAnswers[q.id].length > 0) {
                        nextImmersive();
                    }
                });
                optsContainer.append(confirmBtn);

            } else if (q.type === 'select') {
                const selectEl = $('<select class="immersive-select"></select>');
                const options = q.getOptions();
                options.forEach(function(opt) {
                    const isSelected = imAnswers[q.id] === opt.value;
                    selectEl.append('<option value="' + opt.value + '" ' + (isSelected ? 'selected' : '') + '>' + opt.label + '</option>');
                });
                selectEl.change(function() {
                    const val = $(this).val();
                    if (val) {
                        imAnswers[q.id] = val;
                        checkImmersiveNext();
                    } else {
                        delete imAnswers[q.id];
                        checkImmersiveNext();
                    }
                });
                optsContainer.append(selectEl);
            } else if (q.type === 'select_group') {
                const wrap = $('<div class="immersive-input-wrap"></div>');
                q.selects.forEach(function(sel) {
                    wrap.append('<span class="immersive-input-label">' + sel.label + '</span>');
                    const selectEl = $('<select class="immersive-select"></select>');
                    sel.options.forEach(function(opt) {
                        const isSelected = imAnswers[sel.id] === opt.value;
                        selectEl.append('<option value="' + opt.value + '" ' + (isSelected ? 'selected' : '') + '>' + opt.label + '</option>');
                    });
                    selectEl.change(function() {
                        imAnswers[sel.id] = $(this).val();
                        checkImmersiveNext();
                    });
                    wrap.append(selectEl);
                });
                optsContainer.append(wrap);
            } else if (q.type === 'inputs') {
                const wrap = $('<div class="immersive-input-wrap"></div>');
                q.inputs.forEach(function(inp) {
                    wrap.append('<span class="immersive-input-label">' + inp.label + '</span>');
                    const phText = (typeof inp.placeholder === 'string' && inp.placeholder.indexOf('王二狗') !== -1 && currentLine === 'female') ? inp.placeholder.replace('王二狗', '柳三娘') : inp.placeholder;
                    const inputEl = $('<input type="text" class="immersive-text-input" placeholder="' + phText + '" value="' + (imAnswers[inp.id] !== undefined ? imAnswers[inp.id] : (inp.default || '')) + '" ' + (inp.readonly ? 'readonly' : '') + '>');
                    inputEl.on('input', function() {
                        imAnswers[inp.id] = $(this).val();
                        checkImmersiveNext();
                    });
                    wrap.append(inputEl);
                    if (imAnswers[inp.id] === undefined && inp.default) {
                        imAnswers[inp.id] = inp.default;
                    }
                });
                optsContainer.append(wrap);
            }

            const progressContainer = $('#im-progress');
            progressContainer.empty();
            const validQuestions = [];
            let currentIndexInValid = 0;
            for (let i = 0; i < immersiveQuestions.length; i++) {
                const qItem = immersiveQuestions[i];
                if (!qItem.condition || qItem.condition()) {
                    validQuestions.push(i);
                    if (i === currentImIndex) currentIndexInValid = validQuestions.length - 1;
                }
            }
            for (let i = 0; i < validQuestions.length; i++) {
                let dotClass = 'progress-dot';
                if (i === currentIndexInValid) {
                    dotClass += ' active';
                } else if (i < currentIndexInValid) {
                    dotClass += ' completed';
                }
                progressContainer.append('<div class="' + dotClass + '"></div>');
            }
            checkImmersiveNext();
        }

        function checkImmersiveNext() {
            const q = immersiveQuestions[currentImIndex];
            if (currentImIndex === 0) {
                $('.immersive-nav.prev').addClass('disabled');
            } else {
                $('.immersive-nav.prev').removeClass('disabled');
            }

            let canNext = false;
            if (q.type === 'inputs') {
                canNext = q.inputs.every(function(inp) {
                    if (inp.readonly) return true;
                    if (inp.id === 'im_alias') return true;
                    return imAnswers[inp.id] && imAnswers[inp.id].trim() !== '';
                });
            } else if (q.type === 'multiselect') {
                canNext = imAnswers[q.id] && imAnswers[q.id].length > 0;
            } else if (q.type === 'select_group' || q.optional) {
                canNext = true;
            } else {
                canNext = !!imAnswers[q.id];
            }

            if (q.type === 'multiselect') {
                $('.immersive-nav.next').css('visibility', 'hidden');
            } else {
                $('.immersive-nav.next').css('visibility', 'visible');
                if (canNext) {
                    $('.immersive-nav.next').removeClass('disabled');
                } else {
                    $('.immersive-nav.next').addClass('disabled');
                }
            }

            if (currentImIndex === immersiveQuestions.length - 1 && canNext) {
                if (genderCode() !== lastTalentGender) {
                    initTalentSection();
                }
                $('#im-result-section').slideDown();
            } else {
                $('#im-result-section').slideUp();
            }
        }

        function prevImmersive() {
            if (currentImIndex > 0) {
                let prevIndex = currentImIndex - 1;
                while (prevIndex >= 0 && immersiveQuestions[prevIndex].condition && !immersiveQuestions[prevIndex].condition()) {
                    prevIndex--;
                }
                if (prevIndex >= 0) {
                    currentImIndex = prevIndex;
                    renderImmersiveQuestion();
                }
            }
        }

        function nextImmersive() {
            const q = immersiveQuestions[currentImIndex];
            let canNext = false;
            if (q.type === 'inputs') {
                canNext = q.inputs.every(function(inp) {
                    if (inp.readonly) return true;
                    if (inp.id === 'im_alias') return true;
                    return imAnswers[inp.id] && imAnswers[inp.id].trim() !== '';
                });
            } else if (q.type === 'multiselect') {
                canNext = imAnswers[q.id] && imAnswers[q.id].length > 0;
            } else if (q.type === 'select_group' || q.optional) {
                canNext = true;
            } else {
                canNext = !!imAnswers[q.id];
            }

            if (canNext) {
                if (immersiveQuestions[currentImIndex].id === 'region_type') {
                    delete imAnswers['province'];
                    delete imAnswers['city'];
                }
                let nextIndex = currentImIndex + 1;
                while (nextIndex < immersiveQuestions.length && immersiveQuestions[nextIndex].condition && !immersiveQuestions[nextIndex].condition()) {
                    nextIndex++;
                }
                if (nextIndex < immersiveQuestions.length) {
                    currentImIndex = nextIndex;
                    renderImmersiveQuestion();
                } else {
                    $('#im-result-section').slideDown();
                }
            }
        }

