        function parsePersonaArchive(text) {
            let source = String(text || '');
            const trimmedHead = source.trim().charAt(0);
            if (trimmedHead === '{' || trimmedHead === '[') {
                try {
                    const parsed = JSON.parse(source);
                    const found = [];
                    (function walk(v) {
                        if (typeof v === 'string') {
                            if (v.indexOf('<主角人设（') !== -1) found.push(v);
                        } else if (v && typeof v === 'object') {
                            Object.keys(v).forEach(function(k) { walk(v[k]); });
                        }
                    })(parsed);
                    if (found.length) {
                        found.sort(function(a, b) { return a.length - b.length; });
                        source = found[0];
                    }
                } catch (e) { }
            }
            const blockMatch = source.match(/<主角人设（[^）]*）>([\s\S]*?)<\/主角人设（[^）]*）>/);
            const yaml = blockMatch ? blockMatch[0] : '';
            if (blockMatch) source = blockMatch[1];
            const data = {};
            const experiences = [];
            let section = '';
            source.split('\n').forEach(function(rawLine) {
                const line = rawLine.trim();
                if (!line) return;
                const kv = line.match(/^(本名|化名|性别|年龄|籍贯|出身|外貌|体型|阳具|卵袋|乳房|牝户|体质|惯用手|腰臀|足型)\s*[:：]\s*(.*)$/);
                if (kv) { data[kv[1]] = kv[2].trim(); section = ''; return; }
                const head = line.match(/^(经历|技能|信息控制|当前状态说明)\s*[:：]\s*$/);
                if (head) { section = head[1]; return; }
                const exp = line.match(/^\-\s+(.+)$/);
                if (exp && section === '经历' && experiences.length < 40) experiences.push(exp[1].trim());
            });
            if (!data['身份']) {
                const jobMatch = source.match(/成为无品(?:尚宫局|直殿监)(粗使宫女|普通宫女|女史|火者|司设|长随)/);
                if (jobMatch) data['身份'] = jobMatch[1];
            }
            if (!data['出身'] && experiences.length) {
                const expText = experiences.join('\n');
                const originRules = [
                    ['皇帝替身', ['皇帝有八九分相似', '皇帝替身']],
                    ['巨根扶她（二形）', ['女生男相', '双性器官']],
                    ['穿越者', ['穿越']],
                    ['天家遗脉', ['龙纹玉', '先帝微服', '天家遗脉']],
                    ['罪臣遗孤', ['官宦家庭', '进谏触怒', '流放']],
                    ['娼寮孽种', ['娼妓', '烟花柳巷']],
                    ['市井孤儿', ['街头乞儿']],
                    ['农家子弟', ['农家子弟']],
                    ['世代军户', ['军户']],
                    ['商贾之家', ['买卖', '经营']],
                    ['西域回回', ['西域', '教门']],
                    ['逃嫁之女', ['填房', '出逃']],
                    ['落魄良家', ['家道中落']]
                ];
                for (var oi = 0; oi < originRules.length; oi++) {
                    var matched = false;
                    for (var ki = 0; ki < originRules[oi][1].length; ki++) {
                        if (expText.indexOf(originRules[oi][1][ki]) !== -1) { matched = true; break; }
                    }
                    if (matched) { data['出身'] = originRules[oi][0]; break; }
                }
            }
            if (!data['化名'] && experiences.length) {
                const aliasMatch = experiences.join('\n').match(/在宫中化名['"]([^'"]+)['"]/);
                if (aliasMatch) data['化名'] = aliasMatch[1];
            }
            data['__experiences'] = experiences;
            data['__yaml'] = yaml;
            return data;
        }

        function buildImportYaml(data) {
            if (data.__yaml) return data.__yaml;
            let yaml = '<主角人设（' + (data['本名'] || '<user>') + '）>\n';
            ['本名','化名','性别','年龄','籍贯','出身','外貌','体型','阳具','卵袋','乳房','牝户','体质','惯用手','腰臀','足型'].forEach(function(k) {
                if (data[k]) yaml += k + ': ' + data[k] + '\n';
            });
            if (data.__experiences && data.__experiences.length) {
                yaml += '经历:\n';
                data.__experiences.forEach(function(l) { yaml += '  - ' + l + '\n'; });
            }
            yaml += '当前状态说明:\n  - 本档案仅提供基础背景与过往经历参考\n';
            yaml += '</主角人设（' + (data['本名'] || '<user>') + '）>';
            return yaml;
        }

