        function officialEntryStatus(p, entries) {
            const ent = (entries || []).find(function(e) { return e && eName(e) === p.entryName; });
            if (!ent) return 'missing';
            const a = String(ent.content || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').replace(/\n+$/, '');
            const b = String(p.yaml || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').replace(/\n+$/, '');
            return a === b ? 'ok' : 'altered';
        }

        async function fetchWorldbookSafe(wbName) {
            try { return await getWorldbook(wbName); } catch (e) { return []; }
        }

        async function officialRepairCore(p) {
            let entries = await fetchWorldbookSafe('深宫秋（变量）');
            if (!entries.length) {
                await createWorldbook('深宫秋（变量）', []);
                entries = [];
            }
            const target = entries.find(function(e) { return e && eName(e) === p.entryName; });
            const keepEnabled = target ? target.enabled !== false : false;
            await updateWorldbookWith('深宫秋（变量）', function(current) {
                const rest = current.filter(function(e) { return !(e && eName(e) === p.entryName); });
                return rest.concat([{
                    name: p.entryName, enabled: keepEnabled, content: p.yaml,
                    strategy: { type: 'constant', keys: [], keys_secondary: { logic: 'and_any', keys: [] }, scan_depth: 'same_as_global' },
                    position: { type: 'before_character_definition', order: 25 },
                    probability: 100, recursion: { prevent_incoming: true, prevent_outgoing: false, delay_until: null },
                    effect: { sticky: null, cooldown: null, delay: null }
                }]);
            }, { render: 'immediate' });
        }

        async function repairOfficialPersona(idx) {
