            try {
                await officialRepairCore(p);
                showAlert('提示', '官方人设「' + p.name + '」已复原为官方原文。');
                loadOfficialPersonas();
            } catch (err) {
                showAlert('错误', '复原失败：' + (err && err.message ? err.message : err));
            }
        }

        async function loadOfficialPersonas() {
            officialEntries = typeof getWorldbook === 'function' ? await fetchWorldbookSafe('深宫秋（变量）') : null;
            if (officialSelected < 0 || officialSelected >= OFFICIAL_PERSONAS.length) officialSelected = 0;
            let html = '';
            ['eunuch', 'female'].forEach(function(ln) {
                html += '<div class="official-group-title">' + (ln === 'eunuch' ? '宦官线' : '女官线') + '</div>';
                OFFICIAL_PERSONAS.forEach(function(p, i) {
                    if (p.line !== ln) return;
                    const st = officialEntries ? officialEntryStatus(p, officialEntries) : 'unknown';
                    let badge = '';
                    if (st === 'altered') badge = '<span class="official-badge bad">已改动</span>';
                    else if (st === 'missing') badge = '<span class="official-badge bad">缺失</span>';
                    html += '<div class="official-item' + (i === officialSelected ? ' active' : '') + '" data-idx="' + i + '" onclick="selectOfficialPersona(' + i + ')">'
                        + '<div class="official-seal ' + (ln === 'eunuch' ? 'seal-eunuch' : 'seal-female') + '">' + p.name.charAt(0) + '</div>'
                        + '<div class="official-item-info"><div class="official-item-name">' + p.name + badge + '</div>'
                        + '<div class="official-item-hook">' + p.hook + '</div></div></div>';
                });
            });
            $('#official-list').html(html);
            renderOfficialDetail();
        }

        function selectOfficialPersona(i) {
