            const st = officialEntries ? officialEntryStatus(p, officialEntries) : 'unknown';
            const doc = ent && ent.content ? ent.content : p.yaml;
            let statusLine = '';
            if (st === 'ok') statusLine = '<div class="official-status ok">词条完好，与官方原文一致</div>';
