                } else if (['火者', '司设', '长随'].indexOf(job) > -1) {
                    text += '\n此扶她存档入宫于直殿监，将进入宦官线。';
                    addBtn('扶她 · 宦官线', 'eunuch');
                } else {
                    text += '\n扶她之身两线皆可入局，且未能从存档判断线路，请择其一：';
                    addBtn('扶她 · 宦官线', 'eunuch');
                    addBtn('扶她 · 女官线', 'female');
                }
            } else {
                text += '\n未能识别性别，请自行择路：';
                addBtn('入宦官线', 'eunuch');
                addBtn('入女官线', 'female');
            }
            $('#line-confirm-text').text(text);
            $('#line-confirm-modal').css('display', 'flex').addClass('show');
        }

        function hideLineConfirmModal() {
            $('#line-confirm-modal').hide().removeClass('show');
        }

        async function applyImportedPersona(line, activateOnly) {
            const data = importedData;
            try { await selectLine(line); } catch (e) { console.error(e); }

            const gender = data['性别'] || '';
            const job = data['身份'] || (line === 'female' ? '粗使宫女' : '火者');
            const alias = data['化名'] || (line === 'female' ? '柳三娘' : '王二狗');
            const filled = [];
            const missed = [];

            function fillSelect(label, sel, val) {
                if (!val) return;
                const $s = $(sel);
                if ($s.length && $s.find('option[value="' + val + '"]').length) {
                    $s.val(val).trigger('change');
                    filled.push(label);
                } else {
                    missed.push(label);
                }
            }

            fillSelect('性别', '#dg-gender', gender);
            $('#dg-alias').val(alias);
            filled.push('化名');
            if (data['年龄']) fillSelect('年龄', '#dg-age', String(parseInt(data['年龄'], 10) || 0) + '岁');
            if (data['籍贯']) {
                const parts = data['籍贯'].split(/\s+/);
                fillSelect('籍贯(省)', '#dg-province', parts[0]);
                if (parts[1]) fillSelect('籍贯(府)', '#dg-city', parts[1]);
            }
            fillSelect('出身', '#dg-identity', data['出身']);
            fillSelect('身份', '#dg-job', job);
            if (data['外貌']) {
                if ($('#dg-appearance').find('option[value="' + data['外貌'] + '"]').length) fillSelect('外貌', '#dg-appearance', data['外貌']);
                else { $('#dg-appearance-free').val(data['外貌']); filled.push('外貌(自由文本)'); }
            }
            if (data['体型']) {
                if ($('#dg-body').find('option[value="' + data['体型'] + '"]').length) fillSelect('体型', '#dg-body', data['体型']);
                else { $('#dg-body-free').val(data['体型']); filled.push('体型(自由文本)'); }
            }
            fillSelect('阳具', '#dg-penis', data['阳具']);
            fillSelect('卵袋', '#dg-balls', data['卵袋']);
            fillSelect('乳房', '#dg-breasts', data['乳房']);
            fillSelect('牝户', '#dg-vagina', data['牝户']);
            fillSelect('体质', '#dg-constitution', data['体质']);
            fillSelect('惯用手', '#dg-handedness', data['惯用手']);
            fillSelect('腰臀', '#dg-waisthip', data['腰臀']);
            fillSelect('足型', '#dg-foottype', data['足型']);
            if (data.__experiences && data.__experiences.length) {
                $('#dg-experience').val(data.__experiences.join('\n'));
            }

            const realName = (data['本名'] && data['本名'] !== '<user>') ? data['本名'] : '<user>';
            currentGenData = {
                name: realName,
                alias: alias,
                age: parseInt(data['年龄'], 10) || 18,
                identity: data['出身'] || '穿越者',
                job: job
            };

            let saveError = '';
            try {
                if (activateOnly) {
                    await activatePersonaEntry(archiveModalName);
                } else {
                    await importWritePersona(buildImportYaml(data));
                }
            } catch (err) {
                console.error(err);
                saveError = err && err.message ? err.message : String(err);
            }
            if (saveError) {
                showAlert('错误', '人设写入世界书失败：' + saveError + '\n表单已填好，也可重新走一遍造册手动写入。');
                return;
            }

            $('.btn-select-start').show();
            togglePage('page-select-start');
            showAlert('读取完成',
                '已按「' + (line === 'female' ? '女官线' : '宦官线') + '」' + (activateOnly ? '启用所选人设，' : '') + '填好造册表单，可直接择一开局。\n\n' +
                '已匹配：' + (filled.length ? filled.join('、') : '无') + '\n\n' +
                '未能匹配：' + (missed.length ? missed.join('、') : '无'));
        }


        async function runSelfCheck() {
            const lines = [];
            let ok = true;
            const apis = ['getWorldbook', 'updateWorldbookWith', 'createWorldbook'];
            const missing = apis.filter(function(a) { return typeof window[a] !== 'function'; });
            if (missing.length) {
                ok = false;
                lines.push('【异常】未检测到酒馆助手环境，缺失接口：' + missing.join('、'));
            } else {
                lines.push('【通过】酒馆助手环境正常');
            }
            if (!missing.length) {
                try {
                    const wbName = '深宫秋（变量）';
                    let entries;
                    try { entries = await getWorldbook(wbName); }
                    catch (e) { entries = []; }
                    const hits = (entries || []).filter(function(e) { return e && eName(e) && eName(e).indexOf('主角人设') !== -1 && eName(e).indexOf('主角人设-官方') === -1; });
                    const enabledHits = hits.filter(function(e) { return e.enabled !== false; });
                    if (!hits.length) {
                        lines.push('【提示】卷宗「' + wbName + '」中暂无主角人设词条（尚未捏人或导入）');
                    } else if (enabledHits.length === 1) {
                        lines.push('【通过】开启中的主角人设：' + enabledHits[0].name + (hits.length - enabledHits.length > 0 ? '（另有 ' + (hits.length - enabledHits.length) + ' 条已关闭）' : ''));
                    } else if (enabledHits.length === 0) {
                        ok = false;
                        lines.push('【异常】存在 ' + hits.length + ' 条主角人设词条，但全部处于关闭状态，请读取任一存档或重新捏人');
                    } else {
                        ok = false;
                        lines.push('【异常】多条主角人设词条同时开启：' + enabledHits.map(function(e) { return eName(e); }).join('、') + '。请仅保留一条开启');
                    }
                } catch (e) {
                    ok = false;
                    lines.push('【异常】世界书读取失败：' + (e && e.message ? e.message : e));
                }
            }
            showAlert(ok ? '点验通过' : '点验发现问题', lines.join('\n'));
        }


        function downloadPersonaFile(text, filename) {
            const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = filename;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            setTimeout(function() { URL.revokeObjectURL(url); }, 1000);
        }

        function personaAliasFrom(text) {
            const m = String(text || '').match(/^化名:\s*(.+)$/m);
            if (m) return m[1].trim();
            if (currentGenData && currentGenData.alias) return currentGenData.alias;
            return '未命名';
        }

        function saveResultToLocal() {
            const text = $('#result-modal-text').val();
            if (!text || !text.trim()) { showAlert('提示', '暂无内容可保存！'); return; }
            downloadPersonaFile(text, '深宫秋人设_' + personaAliasFrom(text) + '.txt');
        }

        async function exportPersonaArchive() {
            try {
                const wbName = '深宫秋（变量）';
                let entries;
                try { entries = await getWorldbook(wbName); }
                catch (e) { entries = []; }
                const hit = (entries || []).find(function(e) { return e && eName(e) && eName(e).indexOf('主角人设') !== -1 && e.enabled !== false; })
                    || (entries || []).find(function(e) { return e && eName(e) && eName(e).indexOf('主角人设') !== -1; });
                if (!hit) { showAlert('提示', '卷宗中暂无主角人设词条，请先造册或导入！'); return; }
                downloadPersonaFile(hit.content, '深宫秋人设_' + personaAliasFrom(hit.content) + '.txt');
