            }
        }


        let archiveModalName = '';
        let archiveDelArmed = false;

        function personaUniqueKey(entries, personName) {
            const taken = {};
            (entries || []).forEach(function(e) { if (e && eName(e)) taken[eName(e)] = true; });
            let key = '主角人设（' + personName + '）';
            let n = 1;
            while (taken[key]) {
                key = '主角人设（' + personName + '）-' + n;
                n++;
            }
            return key;
        }

        function personaMergedEntries(entries, entryKey, yaml) {
            const rest = (entries || []).map(function(e) {
                if (e && eName(e) && eName(e).indexOf('主角人设') !== -1) {
                    return Object.assign({}, e, { enabled: false });
                }
                return e;
            });
            return rest.concat([{
                name: entryKey, enabled: true, content: yaml,
                strategy: { type: 'constant', keys: [], keys_secondary: { logic: 'and_any', keys: [] }, scan_depth: 'same_as_global' },
                position: { type: 'before_character_definition', order: 25 },
                probability: 100, recursion: { prevent_incoming: true, prevent_outgoing: false, delay_until: null },
                effect: { sticky: null, cooldown: null, delay: null }
            }]);
        }

        async function activatePersonaEntry(entryName) {
            const wbName = '深宫秋（变量）';
            let entries;
            try { entries = await getWorldbook(wbName); }
            catch (e) { entries = []; }
            const target = (entries || []).find(function(e) { return e && eName(e) === entryName; });
            if (!target) { throw new Error('词条 "' + entryName + '" 不存在或已被删除'); }
            await updateWorldbookWith(wbName, function(current) {
                return current.map(function(e) {
                    if (e && eName(e) && eName(e).indexOf('主角人设') !== -1) {
                        return Object.assign({}, e, { enabled: eName(e) === entryName });
                    }
                    return e;
                });
            }, { render: 'immediate' });
        }

        async function loadLocalArchives() {
            const $list = $('#local-archive-list');
            if (typeof getWorldbook !== 'function') {
                $list.empty().append($('<div class="archive-empty"></div>').text('需要酒馆助手环境才能读取本地存档'));
                return;
            }
            $list.empty().append($('<div class="archive-empty"></div>').text('读取中……'));
            try {
                const wbName = '深宫秋（变量）';
                let entries;
                try { entries = await getWorldbook(wbName); }
                catch (e) { entries = []; }
                const hits = (entries || []).filter(function(e) { return e && eName(e) && eName(e).indexOf('主角人设') !== -1 && eName(e).indexOf('主角人设-官方') === -1; });
                $list.empty();
                if (!hits.length) {
                    $list.append($('<div class="archive-empty"></div>').text('暂无本地存档（捏人或导入后自动保留）'));
                    return;
                }
                hits.forEach(function(e) {
                    const item = $('<div class="archive-item"></div>');
                    item.append($('<div class="archive-item-name"></div>').text(eName(e)));
                    item.append($('<div class="archive-item-state"></div>').text(e.enabled === false ? '关闭' : '开启'));
                    item.on('click', function() { showArchivePreview(eName(e), e.content || ''); });
                    $list.append(item);
                });
            } catch (e) {
                $list.empty().append($('<div class="archive-empty"></div>').text('读取失败：' + (e && e.message ? e.message : e)));
            }
        }

        function showArchivePreview(name, content) {
            archiveModalName = name;
            archiveDelArmed = false;
            $('#archive-modal-title').text(name);
            $('#archive-modal-text').val(content);
            $('#archive-modal-btn-del').text('删除此档');
            $('#archive-modal').css('display', 'flex').addClass('show');
        }

        function hideArchiveModal() {
            $('#archive-modal').hide().removeClass('show');
        }

        function loadSelectedArchive() {
            const text = $('#archive-modal-text').val();
            hideArchiveModal();
            if (!text || !text.trim()) { showAlert('提示', '该存档内容为空！'); return; }
            const data = parsePersonaArchive(text);
            const keys = Object.keys(data).filter(function(k) { return k.indexOf('__') !== 0; });
            if (!keys.length) { showAlert('提示', '未能从该存档解析出人设信息！'); return; }
            importedData = data;
