import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  章回数: z.coerce.number().prefault(1),
  当前城市: z.string().prefault('顺天府'),
  当前地点: z.string().prefault('直殿监'),

  当前时间: z.object({
    年号: z.string().prefault('永昌'),
    年份: z.coerce.number().prefault(3),
    月份: z.coerce.number().prefault(9),
    日期: z.coerce.number().prefault(4),
    节气或节日: z.string().prefault('无'),
    小时: z.coerce.number().prefault(5),
    分钟: z.coerce.number().prefault(0),
    _十二时辰: z.string().prefault('卯初'),
    _二十四小时: z.string().prefault('05:00'),
  }).transform(data => {
    let totalMinutes = data.小时 * 60 + data.分钟;
    let addDays = Math.floor(totalMinutes / (24 * 60));
    totalMinutes = ((totalMinutes % (24 * 60)) + (24 * 60)) % (24 * 60);
    data.小时 = Math.floor(totalMinutes / 60);
    data.分钟 = totalMinutes % 60;

    data.日期 += addDays;
    let addMonths = Math.floor((data.日期 - 1) / 30);
    data.日期 = ((data.日期 - 1) % 30 + 30) % 30 + 1;

    data.月份 += addMonths;
    let addYears = Math.floor((data.月份 - 1) / 12);
    data.月份 = ((data.月份 - 1) % 12 + 12) % 12 + 1;

    data.年份 += addYears;

    const dz = ['子', '丑', '寅', '卯', '辰', '巳', '午', '未', '申', '酉', '戌', '亥'];
    let idx = Math.floor(((data.小时 + 1) % 24) / 2);
    let shichen = dz[idx];
    let jd = (data.小时 % 2 === 0) ? '正' : '初';
    let ke = Math.floor(data.分钟 / 15);
    let keStr = ke === 0 ? '' : ['一', '二', '三'][ke - 1] + '刻';

    data._十二时辰 = `${shichen}${jd}${keStr}`;
    data._二十四小时 = `${String(data.小时).padStart(2, '0')}:${String(data.分钟).padStart(2, '0')}`;

    return data;
  }).prefault({}),

  主角: z.object({
    本名: z.string().prefault('{{user}}'),
    化名: z.string().prefault('{{user}}'),
    年龄: z.coerce.number().prefault(18),
    出身: z.string().prefault('穿越者'),
    境界: z.string().prefault('凡人'),
    身份: z.string().prefault('无品直殿监火者'),
    声望: z.coerce.number().transform(v => _.clamp(v, 0, 1000)).prefault(80),
    _声望阶段: z.string().prefault('微如草芥'),
  }).transform(data => {
    const stages = [
      '微如草芥', '默默无闻', '稍出头角', '小有微名', '颇具体面',
      '周旋有术', '声达宫掖', '近侍天颜', '权柄在握', '权倾朝野'
    ];
    let stageIndex = Math.floor(data.声望 / 100);
    if (stageIndex >= 10) stageIndex = 9;
    data._声望阶段 = stages[stageIndex];
    return data;
  }).prefault({}),

  钱财: z.object({
    金瓜子: z.coerce.number().prefault(0),
    银瓜子: z.coerce.number().prefault(0),
    银子_两: z.coerce.number().prefault(0),
    银子_钱: z.coerce.number().prefault(0),
    银子_分: z.coerce.number().prefault(0),
    铜钱_贯: z.coerce.number().prefault(0),
    铜钱_文: z.coerce.number().prefault(0),
    _余额展示: z.string().prefault('身无分文'),
  }).transform(data => {
    let totalFen = Math.max(0, data.银子_两 * 100 + data.银子_钱 * 10 + data.银子_分);
    data.银子_两 = Math.floor(totalFen / 100);
    data.银子_钱 = Math.floor((totalFen % 100) / 10);
    data.银子_分 = totalFen % 10;

    let totalWen = Math.max(0, data.铜钱_贯 * 1000 + data.铜钱_文);
    data.铜钱_贯 = Math.floor(totalWen / 1000);
    data.铜钱_文 = totalWen % 1000;

    let parts = [];
    if (data.金瓜子 > 0) parts.push(`${data.金瓜子}枚金瓜子`);
    if (data.银瓜子 > 0) parts.push(`${data.银瓜子}枚银瓜子`);

    let yin = [
      data.银子_两 > 0 ? `${data.银子_两}两` : '',
      data.银子_钱 > 0 ? `${data.银子_钱}钱` : '',
      data.银子_分 > 0 ? `${data.银子_分}分` : ''
    ].join('');
    if (yin) parts.push(yin);

    let tong = [
      data.铜钱_贯 > 0 ? `${data.铜钱_贯}贯` : '',
      data.铜钱_文 > 0 ? `${data.铜钱_文}文` : ''
    ].join('');
    if (tong) parts.push(tong);

    data._余额展示 = parts.length > 0 ? parts.join('，') : '身无分文';
    return data;
  }).prefault({}),

  收支账本: z.record(
    z.string().describe('记录唯一标识'),
    z.object({
      时间: z.string().prefault('未知'),
      描述: z.string().prefault(''),
      货币类型: z.enum(['金瓜子', '银瓜子', '银子_两', '银子_钱', '银子_分', '铜钱_贯', '铜钱_文']).prefault({}),
      数量: z.coerce.number().prefault(0).describe('对应货币类型的数量。正为收入，负为支出'),
    }).prefault({})
  ).prefault({}),

  物品栏: z.record(
    z.string().describe('物品名'),
    z.object({
      描述: z.string().prefault(''),
