      let ageNum = data.年龄;
      let isInvalidAge = isNaN(ageNum) || ageNum < 13 || ageNum > 50;
      let canGetPregnant = data.性别 === '女' || data.性别 === '扶她（二形）';
      let isValidTarget = canGetPregnant && !isInvalidAge;

      if (data.生理期.周期天数 === 0) {
        data.生理期.周期天数 = Math.floor(Math.random() * 30) + 1;
      }

      if (isValidTarget) {
        if (!data.孕产.是否怀孕) {
          let days = ((data.生理期.周期天数 - 1) % 30 + 30) % 30 + 1;
          data.生理期.周期天数 = days;

          if (days <= 5) {
            data.生理期._阶段 = '月经期';
            data.生理期._怀孕概率 = '0%';
          } else if (days <= 10) {
            data.生理期._阶段 = '安全期';
            data.生理期._怀孕概率 = '1%';
          } else if (days <= 17) {
            data.生理期._阶段 = '排卵期';
            const probMap = {
              11: '10%', 12: '15%', 13: '20%', 14: '25%', 15: '30%', 16: '20%', 17: '10%'
            };
            data.生理期._怀孕概率 = probMap[days] || '15%';
          } else {
            data.生理期._阶段 = '安全期';
            data.生理期._怀孕概率 = '1%';
          }
        }
        if (data.触发内射结算 && data.触发内射结算.length > 0 && data.孕产.是否怀孕 === false) {
          let prob = parseInt(data.生理期._怀孕概率) || 0;
          if (prob > 0) {
            let randomNum = Math.floor(Math.random() * 100) + 1;
            if (randomNum <= prob) {
              data.孕产.是否怀孕 = true;
              let randomIndex = Math.floor(Math.random() * data.触发内射结算.length);
              data.孕产.胎儿父亲 = data.触发内射结算[randomIndex];
            }
          }
          data.触发内射结算 = [];
        }
        if (data.孕产.是否怀孕) {
          data.生理期._阶段 = '孕期';
          data.生理期._怀孕概率 = '0%';
          if (data.孕产.胎儿数量 === 0) {
            let twinRand = Math.random() * 100;
            if (twinRand < 1) {
              data.孕产.胎儿数量 = 3;
            } else if (twinRand < 5) {
              data.孕产.胎儿数量 = 2;
            } else {
              data.孕产.胎儿数量 = 1;
            }
            data.孕产.男孩数量 = 0;
            data.孕产.女孩数量 = 0;
            for(let i = 0; i < data.孕产.胎儿数量; i++) {
              if(Math.random() < 0.5) {
                data.孕产.男孩数量++;
              } else {
                data.孕产.女孩数量++;
              }
            }
            let details = [];
            if(data.孕产.男孩数量 > 0) details.push(`${data.孕产.男孩数量}男`);
            if(data.孕产.女孩数量 > 0) details.push(`${data.孕产.女孩数量}女`);
            data.孕产._胎儿详情 = details.join('，');

            if (data.孕产.胎儿父亲 === '无' || data.孕产.胎儿父亲 === '') {
                data.孕产.胎儿父亲 = '未知';
            }
          }
        } else {
            data.孕产.胎儿数量 = 0;
            data.孕产.男孩数量 = 0;
            data.孕产.女孩数量 = 0;
            data.孕产._胎儿详情 = '无';
        }
      } else {
        if (data.触发内射结算 && data.触发内射结算.length > 0) {
          data.触发内射结算 = [];
        }
        data.生理期._阶段 = '不可用';
        data.生理期._怀孕概率 = '0%';
        data.孕产.是否怀孕 = false;
        data.孕产.怀孕天数 = 0;
        data.孕产.胎儿父亲 = '无';
        data.孕产.胎儿数量 = 0;
        data.孕产.男孩数量 = 0;
        data.孕产.女孩数量 = 0;
        data.孕产._胎儿详情 = '无';
      }
      return data;
    }).prefault({})
  ).prefault({}),

  事件标记: z.object({
    监军: z.boolean().prefault(false),
    选秀二月初选: z.boolean().prefault(false),
    选秀六月复试: z.boolean().prefault(false),
    选秀八月终选: z.boolean().prefault(false),
    执行跨月结算_月数: z.coerce.number().prefault(0).describe('可手动填入强制跳过月数，或留0靠系统自动比对流逝时间结算'),
  }).prefault({}),

  _系统隐藏: z.object({
    上次结算年份: z.coerce.number().prefault(3),
    上次结算月份: z.coerce.number().prefault(9),
  }).prefault({}),

}).transform(data => {
  let currentYear = data.当前时间.年份;
  let currentMonth = data.当前时间.月份;
  let lastYear = data._系统隐藏.上次结算年份;
  let lastMonth = data._系统隐藏.上次结算月份;

  let timeDiffMonths = (currentYear - lastYear) * 12 + (currentMonth - lastMonth);
  let settleMonths = data.事件标记.执行跨月结算_月数;

  if (timeDiffMonths > 0) {
    settleMonths = Math.max(settleMonths, timeDiffMonths);
  }

  let totalActualMoney = 0;
  let finalActualItems = {};
  let settleDetails = [];

  if (settleMonths > 0) {
    let targetMonths = [];
    for (let i = settleMonths; i >= 1; i--) {
      let m = currentMonth - i;
      while (m <= 0) m += 12;
      targetMonths.push(m);
    }

    _.forOwn(data.产业, (ind, key) => {
      let stateMultiplier = 1.0;
      switch (ind.经营状态) {
        case '繁荣': stateMultiplier = 1.5; break;
        case '平稳': stateMultiplier = 1.0; break;
        case '惨淡': stateMultiplier = 0.5; break;
        case '停滞': stateMultiplier = 0.0; break;
        case '亏损': stateMultiplier = -0.5; break;
      }
      if (ind.经营模式 === '出租' && stateMultiplier < 0) {
        stateMultiplier = 0;
      }

      let indTotalMoney = 0;

      for (let m of targetMonths) {
        let m_isProducing = true;
        if (ind.类型 === '农林' && ind.生产月份 && ind.生产月份.length > 0) {
          m_isProducing = ind.生产月份.includes(m);
        }

        let m_baseMoney = 0;
        let m_baseItems = {};
        if (m_isProducing && ind.经营状态 !== '停滞') {
          m_baseMoney = ind.基础月收益_银子_分 * stateMultiplier;
          _.forOwn(ind.基础月收益_物品, (amount, itemName) => {
            m_baseItems[itemName] = Math.floor(amount * stateMultiplier);
          });
        }

        let m_eventMoney = 0;
        let m_eventItems = {};
        if (ind.本月突发事件.事件名称 !== '无' && ind.本月突发事件.剩余持续月数 > 0) {
          if (ind.经营状态 !== '停滞') {
            m_eventMoney = ind.本月突发事件.银子变动_分;

            if (ind.经营模式 === '出租' && m_eventMoney < 0) {
              m_eventMoney = 0;
            }

            _.forOwn(ind.本月突发事件.物品变动, (amount, itemName) => {
              m_eventItems[itemName] = amount;
            });
          }

          ind.本月突发事件.剩余持续月数 -= 1;
          if (ind.本月突发事件.剩余持续月数 <= 0) {
            ind.本月突发事件 = { 事件名称: '无', 银子变动_分: 0, 物品变动: {}, 剩余持续月数: 0 };
          }
        }

        indTotalMoney += (m_baseMoney + m_eventMoney);

        _.forOwn(m_baseItems, (amount, itemName) => {
          finalActualItems[itemName] = (finalActualItems[itemName] || 0) + amount;
        });
        _.forOwn(m_eventItems, (amount, itemName) => {
          finalActualItems[itemName] = (finalActualItems[itemName] || 0) + amount;
        });
      }

      totalActualMoney += indTotalMoney;
      if (indTotalMoney !== 0) {
         let moneyStr = "";
         let absFen = Math.abs(Math.floor(indTotalMoney));
         let liang = Math.floor(absFen / 100);
         let qian = Math.floor((absFen % 100) / 10);
         let fen = absFen % 10;
         if (liang > 0) moneyStr += `${liang}两`;
         if (qian > 0) moneyStr += `${qian}钱`;
         if (fen > 0) moneyStr += `${fen}分`;
         settleDetails.push(`${ind.名称}${indTotalMoney >= 0 ? '赚' : '亏'}${moneyStr}`);
      }
    });

    let currentFen = (data.钱财.银子_两 * 100) + (data.钱财.银子_钱 * 10) + data.钱财.银子_分;
    let newFen = currentFen + totalActualMoney;

    if (newFen < 0) {
      newFen = 0;
      _.forOwn(data.产业, (ind, key) => {
        ind.经营状态 = '停滞';
      });
      settleDetails.push('资不抵债，产业全停');
    }

    data.钱财.银子_两 = Math.floor(newFen / 100);
    data.钱财.银子_钱 = Math.floor((newFen % 100) / 10);
    data.钱财.银子_分 = Math.floor(newFen % 10);

    _.forOwn(finalActualItems, (amount, itemName) => {
      let addAmount = amount;
      if (addAmount > 0) {
        if (!data.物品栏[itemName]) {
          data.物品栏[itemName] = { 描述: '产业产出', 数量: 0, 位置: '库存' };
        }
        data.物品栏[itemName].数量 += addAmount;
      }
    });

    if (totalActualMoney !== 0 || settleDetails.length > 0) {
      let logKey = `结算_${data.当前时间.年份}年${data.当前时间.月份}月_${Date.now()}`;
      let detailDesc = settleDetails.length > 0 ? `（${settleDetails.join('；')}）` : '';
      data.收支账本[logKey] = {
        时间: `${data.当前时间.年号}${data.当前时间.年份}年${data.当前时间.月份}月`,
        描述: `结算${settleMonths}个月${detailDesc}`,
        货币类型: '银子_分',
        数量: Math.floor(totalActualMoney),
        $time: Date.now()
      };
    }
  }

  data._系统隐藏.上次结算年份 = currentYear;
  data._系统隐藏.上次结算月份 = currentMonth;
  data.事件标记.执行跨月结算_月数 = 0;

  data.收支账本 = _(data.收支账本)
    .entries()
    .sortBy(([k, v]) => v.$time)
    .takeRight(30)
    .fromPairs()
    .value();

  _.forOwn(data.产业, (ind, key) => {
    let isProducingSeason = true;
    if (ind.类型 === '农林' && ind.生产月份 && ind.生产月份.length > 0) {
      isProducingSeason = ind.生产月份.includes(currentMonth);
    }

    let stateMultiplier = 1.0;
    switch (ind.经营状态) {
      case '繁荣': stateMultiplier = 1.5; break;
      case '平稳': stateMultiplier = 1.0; break;
      case '惨淡': stateMultiplier = 0.5; break;
      case '停滞': stateMultiplier = 0.0; break;
      case '亏损': stateMultiplier = -0.5; break;
    }
    if (ind.经营模式 === '出租' && stateMultiplier < 0) {
      stateMultiplier = 0;
    }

    let expectedBaseMoney = 0;
    let expectedBaseItems = {};
    if (isProducingSeason && ind.经营状态 !== '停滞') {
      expectedBaseMoney = ind.基础月收益_银子_分 * stateMultiplier;
      _.forOwn(ind.基础月收益_物品, (amount, itemName) => {
        expectedBaseItems[itemName] = Math.floor(amount * stateMultiplier);
      });
    }

    let expectedTotalMoney = expectedBaseMoney;
    if (ind.经营状态 !== '停滞') {
        let evMoney = ind.本月突发事件.银子变动_分;

        if (ind.经营模式 === '出租' && evMoney < 0) {
            evMoney = 0;
        }
        expectedTotalMoney += evMoney;
    }

    let expectedFinalItems = { ...expectedBaseItems };
    if (ind.经营状态 !== '停滞') {
        _.forOwn(ind.本月突发事件.物品变动, (amount, itemName) => {
          expectedFinalItems[itemName] = (expectedFinalItems[itemName] || 0) + amount;
        });
    }
    _.forOwn(expectedFinalItems, (amount, itemName) => {
      if (amount < 0) expectedFinalItems[itemName] = 0;
    });

    let parts = [];
    if (!isProducingSeason) parts.push('非生产季');
    if (ind.本月突发事件.事件名称 !== '无' && ind.本月突发事件.剩余持续月数 > 0) {
      parts.push(`【突发：${ind.本月突发事件.事件名称}(余${ind.本月突发事件.剩余持续月数}月)】`);
    }

    let actualMoneyDisplay = Math.floor(expectedTotalMoney);
    if (actualMoneyDisplay > 0) {
      let liang = Math.floor(actualMoneyDisplay / 100);
      let qian = Math.floor((actualMoneyDisplay % 100) / 10);
      let fen = actualMoneyDisplay % 10;
      let yin = [
        liang > 0 ? `${liang}两` : '',
        qian > 0 ? `${qian}钱` : '',
        fen > 0 ? `${fen}分` : ''
      ].join('');

      parts.push(`预期进账 ${yin}`);
    } else if (actualMoneyDisplay < 0) {
      let absMoney = Math.abs(actualMoneyDisplay);
      let liang = Math.floor(absMoney / 100);
      let qian = Math.floor((absMoney % 100) / 10);
      let fen = absMoney % 10;
      let yin = [
        liang > 0 ? `${liang}两` : '',
        qian > 0 ? `${qian}钱` : '',
        fen > 0 ? `${fen}分` : ''
      ].join('');
      parts.push(`预期亏空需倒贴 ${yin}`);
    }

    let itemStrs = [];
    _.forOwn(expectedFinalItems, (amount, itemName) => {
      let actualAmount = amount;
      if (actualAmount > 0) itemStrs.push(`${itemName}x${actualAmount}`);
    });
    if (itemStrs.length > 0) parts.push(`预期产出：${itemStrs.join('、')}`);

    if (parts.length === 0 || (parts.length === 1 && parts[0] === '非生产季')) {
      ind._本月预计收益 = parts.length > 0 ? '非生产季，无收益' : '无收益';
    } else {
      ind._本月预计收益 = parts.join('；');
    }
  });

  return data;
}).prefault({});

$(() => {
  registerMvuSchema(Schema);
});

(function() {
    'use strict';

    const SHICHEN_MAP = {
        '子': 23, '丑': 1, '寅': 3, '卯': 5, '辰': 7, '巳': 9,
        '午': 11, '未': 13, '申': 15, '酉': 17, '戌': 19, '亥': 21
    };

    const SHICHEN_RANGE = {
        '子': '23:00-01:00', '丑': '01:00-03:00', '寅': '03:00-05:00',
        '卯': '05:00-07:00', '辰': '07:00-09:00', '巳': '09:00-11:00',
        '午': '11:00-13:00', '未': '13:00-15:00', '申': '15:00-17:00',
        '酉': '17:00-19:00', '戌': '19:00-21:00', '亥': '21:00-23:00'
    };

    function hasAnnotation(text) {
        return /（\d{2}:\d{2}）/.test(text) || /（\d{2}:\d{2}-\d{2}:\d{2}）/.test(text);
    }

    function annotateTime(match, sc, hf, ke) {
        let h = SHICHEN_MAP[sc];
        if (h === undefined) return match;
        h = hf === '初' ? h : (h + 1) % 24;
        let m = 0;
        if (ke) {
            m = ke === '一刻' ? 15 : ke === '二刻' ? 30 : 45;
        }
        return sc + hf + (ke || '') + '（' + String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0') + '）';
    }

    function annotateShichen(match, sc) {
        const range = SHICHEN_RANGE[sc];
        if (range === undefined) return match;
        return sc + '时' + '（' + range + '）';
    }

    function replaceTextNodes($el) {
        $el.contents().each(function() {
            if (this.nodeType === 3) {
                let text = this.nodeValue;

                if (hasAnnotation(text)) return;

                const reFull = /([子丑寅卯辰巳午未申酉戌亥])(初|正)(一刻|二刻|三刻)/g;
                let newText = text.replace(reFull, function(match, sc, hf, ke) {
                    return annotateTime(match, sc, hf, ke);
                });

                const reSimple = /([子丑寅卯辰巳午未申酉戌亥])(初|正)(?!（\d{2}:\d{2}）)(?!一刻|二刻|三刻)/g;
                newText = newText.replace(reSimple, function(match, sc, hf) {
                    return annotateTime(match, sc, hf, null);
                });

                const reShi = /([子丑寅卯辰巳午未申酉戌亥])时(?!（\d{2}:\d{2}-\d{2}:\d{2}）)/g;
                newText = newText.replace(reShi, annotateShichen);

                if (newText !== text) {
                    this.nodeValue = newText;
                }
            } else if (this.nodeType === 1) {
                replaceTextNodes($(this));
            }
        });
    }

    function processMessage(messageId) {
        const $el = retrieveDisplayedMessage(messageId);
        if (!$el || !$el.length) return;
        replaceTextNodes($el);
    }

    const safeProcess = errorCatched(processMessage);

    $(() => {
        setTimeout(() => {
            const lastId = getLastMessageId();
            for (let i = 0; i <= lastId; i++) {
                safeProcess(i);
            }
        }, 500);
    });
    eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, safeProcess);
    eventOn(tavern_events.USER_MESSAGE_RENDERED, safeProcess);
    eventOn(tavern_events.MESSAGE_SWIPED, safeProcess);
    eventOn(tavern_events.MESSAGE_UPDATED, safeProcess);
    eventOn(tavern_events.MESSAGE_RENDERED, safeProcess);

    console.log('[时辰标注] 脚本已启动');
})();

