    const buildCardGrid = function(groups, itemType, cardClass, titleClass, descField) {
      var html = '';
      for (var gi = 0; gi < groups.length; gi++) {
        var g = groups[gi];
        html += '<div class="fzj-char-section">' + esc(g.name) + '</div>';
        html += '<div class="'+cardClass+'">';
        for (var ii = 0; ii < g.items.length; ii++) {
          var it = g.items[ii];
          var desc = '';
          if (descField === 'summary') {
            desc = getCharSummary(it.key);
          } else {
            var data = loreInfoData[it.key] || '';
            var dm = data.match(/描述[：:]([^\n]+)/);
            var cm = data.match(/核心[：:]([^\n]+)/);
            if (dm && dm[1]) desc = dm[1];
            else if (cm && cm[1]) desc = cm[1];
            else desc = data.replace(/【[^】]+】\n?/, '').substring(0, 40);
          }
          html += '<div class="fzj-'+itemType+'-card" data-key="' + esc(it.key) + '">' +
            '<div class="'+titleClass+'" data-cat="' + esc(it.cat || '') + '">' + esc(it.label) + '</div>' +
