    const formatModalBody = function(text) {
      var lines = text.split('\n');
      var html = '';
      for (var i = 0; i < lines.length; i++) {
        var line = lines[i];
        if (line === '') { html += '<br>'; continue; }
        if (/^【.*?】\s*$/.test(line)) continue;
        var fm = line.match(/^(年龄|身份|居所|性格|现状|党魁|核心|主张|势力关系|构成|描述|驾崩时|病逝时|包含)[：:](.*)$/);
        if (fm) {
          html += '<span class="fzj-field-label">' + esc(fm[1]) + '：</span>' + esc(fm[2]) + '<br>';
          continue;
        }
        var nm = line.match(/^(【.*?】)(.*)$/);
        if (nm) {
          html += '<b>' + nm[1] + '</b>' + esc(nm[2]) + '<br>';
          continue;
        }
        html += esc(line) + '<br>';
      }
      return html;
    };

