    const createModal = function() {
      if (modalOverlay) return;
      modalOverlay = pD.createElement('div');
      modalOverlay.className = 'fzj-modal-overlay';
      modalOverlay.innerHTML = '<div class="fzj-modal-content">' +
        '<button class="fzj-modal-close" id="fzj-modal-close-btn">×</button>' +
        '<div class="fzj-modal-title" id="fzj-modal-title"></div>' +
        '<div class="fzj-modal-body" id="fzj-modal-body"></div></div>';
      pD.body.appendChild(modalOverlay);
      var mc = modalOverlay.querySelector('#fzj-modal-close-btn');
      mc.addEventListener('click', closeModal);
      modalOverlay.addEventListener('click', function(e) { if (e.target === modalOverlay) closeModal(); });
    };

    const showModal = function(key) {
      var data = loreInfoData[key];
      if (!data) return;
      if (!modalOverlay) createModal();
      var mt = modalOverlay.querySelector('#fzj-modal-title');
      var mb = modalOverlay.querySelector('#fzj-modal-body');
      if (mt) mt.innerHTML = esc(key);
      if (mb) mb.innerHTML = formatModalBody(data);
      bodyOverflow = pD.body.style.overflow;
      pD.body.style.overflow = 'hidden';
      modalOverlay.classList.add('active');
      modalOpen = true;
    };

    const closeModal = function() {
      if (modalOverlay) {
        modalOverlay.classList.remove('active');
        pD.body.style.overflow = bodyOverflow;
        bodyOverflow = '';
        modalOpen = false;
      }
    };

    var searchTimer = null;

    const doSearch = function(query, dlg, showAll) {
      var resultsDiv = dlg.querySelector('#fzj-search-results');
      var resultsGrid = dlg.querySelector('#fzj-search-grid');
      var defaultContent = dlg.querySelector('#fzj-default-content');
      var searchMore = dlg.querySelector('#fzj-search-more');
      if (!resultsDiv || !resultsGrid || !defaultContent || !searchMore) return;
      if (query === '') {
        resultsDiv.style.display = 'none';
        defaultContent.style.display = 'block';
        return;
      }
      defaultContent.style.display = 'none';
      resultsDiv.style.display = 'block';
      resultsGrid.innerHTML = '';
      var matches = [];
      for (var key in loreInfoData) {
        if (!loreInfoData.hasOwnProperty(key)) continue;
        if (key.toLowerCase().includes(query) || loreInfoData[key].toLowerCase().includes(query)) {
          matches.push(key);
        }
      }
      if (matches.length === 0) {
        resultsGrid.innerHTML = '<div class="fzj-no-results">未寻得相关卷宗...</div>';
        searchMore.style.display = 'none';
        return;
      }
      var limit = showAll ? matches.length : 12;
      var hasMore = matches.length > 12 && !showAll;
      for (var i = 0; i < Math.min(matches.length, limit); i++) {
        (function(k) {
          var chip = pD.createElement('span');
          chip.className = 'fzj-chip';
          chip.textContent = k;
          chip.setAttribute('data-key', k);
          chip.addEventListener('click', function() { if (loreInfoData[k]) showModal(k); });
          resultsGrid.appendChild(chip);
        })(matches[i]);
      }
      if (hasMore) {
        searchMore.style.display = 'block';
        searchMore.textContent = '…还有 ' + (matches.length - 12) + ' 条';
        searchMore.onclick = function() { doSearch(query, dlg, true); };
      } else {
        searchMore.style.display = 'none';
      }
    };

    const bindEvents = function(dlg) {
      dlg.querySelectorAll('.fzj-tab-btn').forEach(function(btn) {
        btn.addEventListener('click', function() {
          var tab = btn.getAttribute('data-tab');
          var si = dlg.querySelector('#fzj-search-input');
          if (si) { si.value = ''; doSearch('', dlg); }
          dlg.querySelectorAll('.fzj-tab-btn').forEach(function(b) { b.classList.remove('active'); });
          btn.classList.add('active');
          dlg.querySelectorAll('.fzj-panel').forEach(function(p) { p.classList.remove('active'); });
          var tp = dlg.querySelector('#fzj-panel-' + tab);
          if (tp) tp.classList.add('active');
          var main = dlg.querySelector('#fzj-main');
          if (main) main.scrollTop = 0;
        });
      });

      dlg.querySelectorAll('.fzj-org-header').forEach(function(hdr) {
        hdr.addEventListener('click', function() {
          var g = hdr.parentElement;
          if (g && g.classList.contains('fzj-org-group')) g.classList.toggle('collapsed');
        });
      });

      dlg.querySelectorAll('.fzj-org-sub-header').forEach(function(hdr) {
        hdr.addEventListener('click', function() {
          var s = hdr.parentElement;
          if (s && s.classList.contains('fzj-org-sub')) s.classList.toggle('collapsed');
        });
      });

      dlg.querySelectorAll('.fzj-char-card').forEach(function(el) {
        el.addEventListener('click', function() {
          var key = el.getAttribute('data-key');
          if (key && loreInfoData[key]) showModal(key);
        });
      });

      dlg.querySelectorAll('.fzj-faction-card').forEach(function(el) {
        el.addEventListener('click', function() {
          var key = el.getAttribute('data-key');
          if (key && loreInfoData[key]) showModal(key);
        });
      });

      dlg.querySelectorAll('.fzj-map-cell').forEach(function(el) {
        el.addEventListener('click', function() {
          var key = el.getAttribute('data-key');
          if (key && loreInfoData[key]) showModal(key);
        });
      });

      dlg.querySelectorAll('.fzj-chip').forEach(function(el) {
        el.addEventListener('click', function() {
          var key = el.getAttribute('data-key');
          if (key && loreInfoData[key]) showModal(key);
        });
      });

      var searchInput = dlg.querySelector('#fzj-search-input');
      if (searchInput) {
        searchInput.addEventListener('input', function(e) {
          var val = e.target.value.trim().toLowerCase();
          if (searchTimer) clearTimeout(searchTimer);
          if (val === '') { doSearch('', dlg); return; }
          searchTimer = setTimeout(function() { doSearch(val, dlg, false); }, 200);
        });
        searchInput.addEventListener('keydown', function(e) {
          if (e.key === 'Escape') {
            searchInput.value = ''; doSearch('', dlg); searchInput.blur(); return;
          }
          if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
            e.preventDefault();
            var chips = dlg.querySelectorAll('#fzj-search-grid .fzj-chip');
            if (chips.length === 0) return;
            var focused = dlg.querySelector('#fzj-search-grid .fzj-chip:focus');
            var idx = -1;
            if (focused) { for (var i = 0; i < chips.length; i++) { if (chips[i] === focused) { idx = i; break; } } }
            idx = (e.key === 'ArrowDown') ? (idx + 1) % chips.length : (idx - 1 + chips.length) % chips.length;
            chips[idx].focus();
          }
          if (e.key === 'Enter') {
            var fc = dlg.querySelector('#fzj-search-grid .fzj-chip:focus');
            if (fc) {
              var key = fc.getAttribute('data-key');
              if (key && loreInfoData[key]) showModal(key);
            }
          }
        });
      }
    };

