    var fzjMainOpen = false;

    const openFengWuZhi = function() {
      if (fzjOverlay) return;
      fzjOverlay = pD.createElement('div');
      fzjOverlay.id = 'fzj-overlay';

      var dlg = pD.createElement('div');
      dlg.id = 'fzj-dialog';

      var header = pD.createElement('div');
      header.className = 'fzj-header';
      header.innerHTML =
        '<button class="fzj-header-close" id="fzj-header-close-btn">×</button>' +
        '<div class="fzj-header-title-wrap">' +
          '<span class="fzj-header-line"></span>' +
