      dlg.appendChild(header);

      var main = pD.createElement('div');
      main.className = 'fzj-main';
      main.id = 'fzj-main';

      var builds = ['bg', 'factions', 'orgs', 'geo', 'chars'];
      var panelsHtml = '';
      for (var pi = 0; pi < builds.length; pi++) {
        panelsHtml += '<div class="fzj-panel' + (pi === 0 ? ' active' : '') + '" id="fzj-panel-' + builds[pi] + '">' + panelHtml[builds[pi]] + '</div>';
      }

      main.innerHTML = '<div class="fzj-search-wrap">' +
        '<input type="text" class="fzj-search-input" id="fzj-search-input" placeholder="输入词条名称或内容寻阅..." spellcheck="false">' +
        '</div>' +
        '<div class="fzj-search-results" id="fzj-search-results">' +
        '<div class="fzj-search-grid" id="fzj-search-grid"></div>' +
        '<div class="fzj-search-more" id="fzj-search-more" style="display:none;"></div></div>' +
        '<div id="fzj-default-content">' +
        '<div class="fzj-tabs">' +
        '<button class="fzj-tab-btn active" data-tab="bg">旧朝影事</button>' +
        '<button class="fzj-tab-btn" data-tab="factions">朝野暗流</button>' +
        '<button class="fzj-tab-btn" data-tab="orgs">内廷司局</button>' +
        '<button class="fzj-tab-btn" data-tab="geo">皇城堪舆</button>' +
        '<button class="fzj-tab-btn" data-tab="chars">宫闱人物</button>' +
        '</div>' +
        panelsHtml +
        '</div>';

      dlg.appendChild(main);
      fzjOverlay.appendChild(dlg);
      HOST.appendChild(fzjOverlay);

      dlg.querySelector('#fzj-header-close-btn').addEventListener('click', exitSelf);
      fzjOverlay.addEventListener('click', function(e) { if (e.target === fzjOverlay) exitSelf(); });

      bindEvents(dlg);
      fzjMainOpen = true;
    };

    const closeFengWuZhi = function() {
      if (fzjOverlay) {
        closeModal();
        if (modalOverlay) {
          modalOverlay.remove();
          modalOverlay = null;
        }
        fzjOverlay.remove();
        fzjOverlay = null;
        fzjMainOpen = false;
      }
    };


    const ensureFont = function() {
      if (pD.querySelector('link[href*="Ma+Shan+Zheng"]')) return;
      var fontLink = pD.createElement('link');
      fontLink.rel = 'stylesheet';
      fontLink.href = 'https://fonts.googleapis.com/css2?family=Ma+Shan+Zheng&family=Noto+Serif+SC:wght@400;500;600;700;900&family=ZCOOL+XiaoWei&display=swap';
      (pD.head || pD.body).appendChild(fontLink);
    };

    const exitSelf = function() {
      closeFengWuZhi();
      if (NAV && NAV.back) NAV.back();
    };

    return {
      slug: 'fzj',
      mount: function(host, nav) {
        NAV = nav || null;
        HOST = host || pD.body;
        ensureFont();
        injectCSS();
        openFengWuZhi();
      },
      unmount: function() { closeFengWuZhi(); },
      escape: function() {
        if (modalOpen) { closeModal(); return true; }
        return false;
      }
    };
  })();

