  var OV = null;
  var $g = function(id) { return OV ? OV.querySelector('#' + id) : pD.getElementById(id); };
  var state = {
    mode: 'status',
    balSilver: 0,
    balCopper: 0,
    netSilver: 0,
    netCopper: 0,
    betSilver: 0,
    betCopper: 0,
    zone: null,
    playMode: 'A',
    rolling: false,
    log: []
  };

  var CN = ['一', '二', '三', '四', '五', '六', '七', '八', '九', '十'];
  var cnNum = function(n) {
    return n <= 10 ? '第' + CN[n - 1] + '局' : '第' + n + '局';
  };
  var fmtSilver = function(w) {
    var neg = w < 0;
    w = Math.abs(w);
    var liang = Math.floor(w / 1000), qian = Math.floor((w % 1000) / 100), fen = Math.floor((w % 100) / 10);
    var s = '';
    if (liang > 0) s += liang + '两';
    if (qian > 0) s += qian + '钱';
    if (fen > 0 || s === '') s += fen + '分';
    return (neg ? '-' : '') + '银' + s;
  };
  var fmtCopper = function(w) {
    var neg = w < 0;
    w = Math.abs(w);
    var guan = Math.floor(w / 1000), wen = w % 1000;
    var s = '';
    if (guan > 0) s += guan + '贯';
    if (wen > 0 || s === '') s += wen + '文';
    return (neg ? '-' : '') + '铜钱' + s;
  };

  var getMvuMoney = function(cb) {
    var finished = false;
    var done = function(v) { if (finished) return; finished = true; cb(v); };
    var timer = null;
    try {
      if (typeof waitGlobalInitialized !== 'function') { done(null); return; }
      timer = setTimeout(function() { done(null); }, 3000);
      waitGlobalInitialized('Mvu').then(function() {
        clearTimeout(timer);
        try {
          if (typeof Mvu !== 'undefined' && typeof Mvu.getMvuData === 'function') {
            var data = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
            var sd = data && data.stat_data ? data.stat_data : null;
            var m = sd && sd.钱财 && typeof sd.钱财 === 'object' ? sd.钱财 : null;
            done(m);
            return;
          }
        } catch (e) {}
        done(null);
      }).catch(function() { clearTimeout(timer); done(null); });
    } catch (e) { if (timer) clearTimeout(timer); done(null); }
  };
  var getLastStatusText = function() {
    var want = function(m) {
      return m && (m.indexOf('实时情况') !== -1 || m.indexOf('钱财') !== -1 || /钱财[：:]/.test(m));
    };
    try {
      if (typeof getChatMessages !== 'function') return '';
      var cm = getChatMessages(-1);
      if (cm && cm.length && want(cm[0].message)) return cm[0].message;
      var pm = getChatMessages(-2);
      if (pm && pm.length && want(pm[0].message)) return pm[0].message;
    } catch (e) {}
    return '';
  };
  var parseStatus = function(text) {
    var lines = text.split('\n');
    var hits = [];
    for (var i = 0; i < lines.length; i++) {
      if (/钱财[：:]/.test(lines[i])) hits.push(lines[i]);
    }
    if (!hits.length) return null;
    var m = hits[hits.length - 1].match(/钱财[：:]\s*(.*)/);
    if (!m) return null;
    var silver = 0, copper = 0, found = false;
    var tokens = m[1].split(/\s+/);
    for (var t = 0; t < tokens.length; t++) {
      var tok = tokens[t].replace(/[，,、；;。]/g, '');
      var mm, sl, sq, sf, cg, cw;
      if ((mm = tok.match(/金瓜子×(\d+)/))) { silver += parseInt(mm[1], 10) * 10000; found = true; continue; }
      if ((mm = tok.match(/银瓜子×(\d+)/))) { silver += parseInt(mm[1], 10) * 1000; found = true; continue; }
      if (/^银×/.test(tok)) {
        sl = (tok.match(/(\d+)两/) || [])[1];
        sq = (tok.match(/(\d+)钱/) || [])[1];
        sf = (tok.match(/(\d+)分/) || [])[1];
        if (sl || sq || sf) { silver += parseInt(sl || 0, 10) * 1000 + parseInt(sq || 0, 10) * 100 + parseInt(sf || 0, 10) * 10; found = true; }
        continue;
      }
      if (/^铜钱×/.test(tok)) {
        cg = (tok.match(/(\d+)贯/) || [])[1];
        cw = (tok.match(/(\d+)文/) || [])[1];
        if (cg || cw) { copper += parseInt(cg || 0, 10) * 1000 + parseInt(cw || 0, 10); found = true; }
      }
    }
    return found ? { silver: silver, copper: copper } : null;
  };
  var refreshFromSource = function(cb) {
    getMvuMoney(function(v) {
      if (v) {
        state.mode = 'var';
        state.balSilver = (parseInt(v.金瓜子, 10) || 0) * 10000 + (parseInt(v.银瓜子, 10) || 0) * 1000
          + (parseInt(v.银子_两, 10) || 0) * 1000 + (parseInt(v.银子_钱, 10) || 0) * 100 + (parseInt(v.银子_分, 10) || 0) * 10;
        state.balCopper = (parseInt(v.铜钱_贯, 10) || 0) * 1000 + (parseInt(v.铜钱_文, 10) || 0);
      } else {
        state.mode = 'status';
        var b = parseStatus(getLastStatusText());
        state.balSilver = b ? b.silver : 0;
        state.balCopper = b ? b.copper : 0;
      }
      if (cb) cb();
    });
  };

  var totalSilver = function() { return state.balSilver + state.netSilver; };
  var totalCopper = function() { return state.balCopper + state.netCopper; };
  var zoneName = function(k) {
    if (k === 'big') return '大';
    if (k === 'small') return '小';
    if (k === 'triple') return '围骰';
    if (k === 'win') return '我胜';
