  };
  var betText = function() {
    var parts = [];
    if (state.betSilver > 0) parts.push(fmtSilver(state.betSilver));
    if (state.betCopper > 0) parts.push(fmtCopper(state.betCopper));
    return parts.length ? parts.join(' ') : '';
  };

  var refreshChips = function() {
    var chips = (OV || pD).querySelectorAll('.gb-chip');
    for (var i = 0; i < chips.length; i++) {
      var cu = parseInt(chips[i].getAttribute('data-cu'), 10) || 0;
      var sv = parseInt(chips[i].getAttribute('data-sv'), 10) || 0;
      var dis = (cu > 0 && cu > totalCopper()) || (sv > 0 && sv > totalSilver());
      chips[i].disabled = dis;
      chips[i].style.opacity = dis ? '0.38' : '1';
    }
  };
  var refreshBal = function() {
    var main = $g('gb-bal-main');
    if (!main) return;
    main.innerHTML = '<span class="gb-bs">' + fmtSilver(totalSilver()) + '</span> <span class="gb-bc">' + fmtCopper(totalCopper()) + '</span>';
    var sub = $g('gb-bal-sub');
    var parts = [];
    if (state.netSilver !== 0) parts.push('<span class="' + (state.netSilver > 0 ? 'gb-up' : 'gb-down') + '">银' + (state.netSilver > 0 ? '+' : '') + fmtSilver(Math.abs(state.netSilver)).replace(/^银/, '') + '</span>');
    if (state.netCopper !== 0) parts.push('<span class="' + (state.netCopper > 0 ? 'gb-up' : 'gb-down') + '">铜钱' + (state.netCopper > 0 ? '+' : '') + fmtCopper(Math.abs(state.netCopper)).replace(/^铜钱/, '') + '</span>');
    var netTxt = parts.length ? parts.join(' ') : '<span class="gb-none">无变化</span>';
    sub.innerHTML = '<div>初始 ' + fmtSilver(state.balSilver) + ' ' + fmtCopper(state.balCopper) + '</div><div>本次开桌净变化 ' + netTxt + '</div>';
    refreshChips();
  };
  var renderZones = function() {
    var box = $g('gb-zones');
    if (!box) return;
    box.innerHTML = '';
    var zones = state.playMode === 'A'
      ? [{ key: 'big', name: '大', odds: '1赔1' }, { key: 'small', name: '小', odds: '1赔1' }, { key: 'triple', name: '围骰', odds: '1赔24' }]
      : [{ key: 'win', name: '我胜', odds: '1赔1' }];
    for (var i = 0; i < zones.length; i++) {
      (function(z) {
        var d = pD.createElement('div');
        d.className = 'gb-zone' + (state.zone === z.key ? ' picked' : '');
        d.innerHTML = '<div class="gb-zn">' + z.name + '</div><div class="gb-zo">' + z.odds + '</div><div class="gb-zb">' + (state.zone === z.key ? betText() : '') + '</div>';
        d.addEventListener('click', function() {
          if (state.rolling) return;
          if (state.zone === z.key) {
            state.netSilver += state.betSilver;
            state.netCopper += state.betCopper;
            state.zone = null;
          } else {
            if (state.betSilver > 0 && state.betSilver > totalSilver()) { alert('银子不够（现有 ' + fmtSilver(totalSilver()) + '）'); return; }
            if (state.betCopper > 0 && state.betCopper > totalCopper()) { alert('铜钱不够（现有 ' + fmtCopper(totalCopper()) + '）'); return; }
            if (!state.betSilver && !state.betCopper) { alert('先填下注金额'); return; }
            if (state.betCopper > 0 && state.betCopper < 10) { alert('铜钱最低下注10文'); return; }
            if (state.betSilver > 0 && state.betSilver < 10) { alert('银子最低下注1分'); return; }
            if (state.zone) { state.netSilver += state.betSilver; state.netCopper += state.betCopper; }
            state.netSilver -= state.betSilver;
            state.netCopper -= state.betCopper;
            state.zone = z.key;
          }
          renderZones();
          refreshBal();
        });
        box.appendChild(d);
      })(zones[i]);
    }
  };

  var paintDie = function(el, v) {
    el.innerHTML = '';
    var map = {
      1: [4], 2: [0, 8], 3: [0, 4, 8], 4: [0, 2, 6, 8],
      5: [0, 2, 4, 6, 8], 6: [0, 2, 3, 5, 6, 8]
    };
    var dots = map[v];
    for (var i = 0; i < 9; i++) {
      var cell = pD.createElement('div');
      if (dots.indexOf(i) !== -1) {
        var pip = pD.createElement('div');
