  var rakeSilver = function(prize) { return Math.round(prize * 0.1 / 10) * 10; };
  var rakeCopper = function(prize) { return Math.round(prize * 0.1); };

  var settleA = function(vals) {
    var sum = vals[0] + vals[1] + vals[2];
    var isTriple = vals[0] === vals[1] && vals[1] === vals[2];
    var win = false;
    if (state.zone === 'big') win = !isTriple && sum >= 11 && sum <= 17;
    if (state.zone === 'small') win = !isTriple && sum >= 4 && sum <= 10;
    if (state.zone === 'triple') win = isTriple;
    var openTxt = isTriple ? '围骰' : (sum >= 11 ? '大' : '小');
    var silverTxt = '', copperTxt = '';
    if (win) {
      var ps = state.betSilver * 1, pc = state.betCopper * 1;
      if (state.zone === 'triple') { ps *= 24; pc *= 24; }
      if (state.betSilver > 0) {
        var rs = rakeSilver(ps), gs = ps - rs;
        state.netSilver += state.betSilver + gs;
        silverTxt = '银赢' + fmtSilver(gs).replace(/^银/, '') + '（抽水' + fmtSilver(rs).replace(/^银/, '') + '）';
      }
      if (state.betCopper > 0) {
        var rc = rakeCopper(pc), gc = pc - rc;
        state.netCopper += state.betCopper + gc;
        copperTxt = '铜钱赢' + fmtCopper(gc).replace(/^铜钱/, '') + '（抽水' + fmtCopper(rc).replace(/^铜钱/, '') + '）';
      }
    } else {
      if (state.betSilver > 0) silverTxt = '银输' + fmtSilver(state.betSilver).replace(/^银/, '');
      if (state.betCopper > 0) copperTxt = '铜钱输' + fmtCopper(state.betCopper).replace(/^铜钱/, '');
    }
    var roundTxt = cnNum(state.log.length + 1) + '：押' + betText() + '，开 ' + vals.join('·') + '（' + sum + '点' + (isTriple ? '·围骰通杀' : '·' + openTxt) + '），' + [silverTxt, copperTxt].filter(Boolean).join('，');
    state.zone = null;
    renderZones();
    refreshBal();
    showResult(roundTxt, win ? 1 : -1);
  };

  var sheep = function(dice) {
    var a = dice[0], b = dice[1], c = dice[2];
    if (a === b && b === c) return { type: '老羊', val: a };
    if (a === b) return { type: '羊', val: c };
    if (a === c) return { type: '羊', val: b };
    if (b === c) return { type: '羊', val: a };
    return { type: '散', val: 0 };
  };
  var sheepTxt = function(s) {
    if (s.type === '老羊') return '老羊' + s.val + '点';
    if (s.type === '羊') return s.val + '点羊';
    return '散';
  };
  var settleB = function(p, s) {
    var ps = sheep(p), ss = sheep(s);
    var roundTxt, flag = 0;
    if (ps.type === '散' && ss.type === '散') {
      state.netSilver += state.betSilver; state.netCopper += state.betCopper;
      roundTxt = cnNum(state.log.length + 1) + '：双方皆散，重掷（退注' + betText() + '）';
    } else if (ps.type === '散') {
      state.netSilver += state.betSilver; state.netCopper += state.betCopper;
      roundTxt = cnNum(state.log.length + 1) + '：你掷散，作废重掷（退注' + betText() + '）';
    } else if (ss.type === '散') {
      state.netSilver += state.betSilver; state.netCopper += state.betCopper;
      roundTxt = cnNum(state.log.length + 1) + '：庄掷散，作废重掷（退注' + betText() + '）';
    } else {
      var pv = ps.type === '老羊' ? ps.val + 100 : ps.val;
