          state.netCopper += state.betCopper + gc;
          copperTxt = '铜钱赢' + fmtCopper(gc).replace(/^铜钱/, '') + '（抽水' + fmtCopper(rc).replace(/^铜钱/, '') + '）';
        }
        roundTxt = head + '，' + [silverTxt, copperTxt].filter(Boolean).join('，');
      } else if (pv < sv) {
        flag = -1;
        if (state.betSilver > 0) silverTxt = '银输' + fmtSilver(state.betSilver).replace(/^银/, '');
        if (state.betCopper > 0) copperTxt = '铜钱输' + fmtCopper(state.betCopper).replace(/^铜钱/, '');
        roundTxt = head + '，' + [silverTxt, copperTxt].filter(Boolean).join('，');
      } else {
        state.netSilver += state.betSilver; state.netCopper += state.betCopper;
        roundTxt = head + '，平局退' + betText();
      }
    }
    state.zone = null;
