    if (state.netSilver !== 0) parts.push((state.netSilver > 0 ? '银+' : '银-') + fmtSilver(Math.abs(state.netSilver)).replace(/^银/, ''));
    if (state.netCopper !== 0) parts.push((state.netCopper > 0 ? '铜钱+' : '铜钱-') + fmtCopper(Math.abs(state.netCopper)).replace(/^铜钱/, ''));
