    var m; while ((m = re.exec(t)) !== null) {
      var vn = m[1], dv = m[2], pr = m[3], md = m[4] ? parseInt(m[4]) : 2;
      if (!R.includes(vn.toLowerCase()) && !arr.find(function(x) { return x.varName === vn; })) {
        arr.push({ varName: vn, defVal: dv, prompt: pr, mode: md });
      }
    }
    return arr;
  };

  var processString = async function(str) {
    var s = str;
    var vars = getVars();
