function asDoc() {
    try {
        const d = window.parent && window.parent.document;
        if (d && d.body) return d;
    } catch (e) { }
    return document;
}

function asWin() {
    try {
        if (window.parent && window.parent.document) return window.parent;
    } catch (e) { }
    return window;
}

function asCharData() {
    try {
        if (typeof getCharData === 'function') return getCharData('current');
    } catch (e) { }
