    return ch.name || (ch.data && ch.data.name) || '当前角色';
}

function asClip(s, n) {
    const t = String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
    return t.length > n ? t.slice(0, n - 1) + '…' : t;
}

function asCardList() {
    const out = [];
    const seen = new Set();
    for (const it of asNormalize(AS_BOARDS)) {
        if (seen.has(it.url)) continue;
        seen.add(it.url);
        out.push(it);
    }
    return out;
}

function asFileName(url) {
    try {
        const base = (asWin().location && asWin().location.href) || undefined;
        const u = new URL(url, base);
        const seg = u.pathname.split('/').filter(Boolean).pop() || '';
        const dot = seg.lastIndexOf('.');
        const name = dot > 0 ? seg.slice(0, dot) : seg;
        return decodeURIComponent(name) || url;
    } catch (e) {
        const seg = String(url).split('/').pop() || String(url);
        const dot = seg.lastIndexOf('.');
        return dot > 0 ? seg.slice(0, dot) : seg;
    }
}

function asNormalize(raw) {
    if (!Array.isArray(raw)) return [];
    const out = [];
    for (const it of raw) {
        if (typeof it === 'string') {
            const url = it.trim();
            if (url) out.push({ name: asFileName(url), url });
        } else if (it && typeof it === 'object') {
            const url = String(it[AS_ITEM_URL] ?? it.url ?? '').trim();
            if (!url) continue;
            const name = String(it[AS_ITEM_NAME] ?? it.name ?? '').trim();
            out.push({ name: name || asFileName(url), url });
        }
    }
    return out;
}

function asReadTable() {
    try {
        const v = getVariables({ type: 'global' });
        const t = v && v[AS_VAR_TABLE];
        return t && typeof t === 'object' && !Array.isArray(t) ? t : {};
    } catch (e) {
        return {};
    }
}

function asTableGet(cardFile) {
    if (!cardFile) return {};
    const rec = asReadTable()[cardFile];
    return rec && typeof rec === 'object' ? rec : {};
}

function asTableSet(cardFile, patch) {
    if (!cardFile) return;
    try {
        insertOrAssignVariables(
            { [AS_VAR_TABLE]: { [cardFile]: Object.assign({}, asTableGet(cardFile), patch) } },
            { type: 'global' },
        );
    } catch (e) {
        console.error('[卡面替换] 写入失败', e);
    }
}

function asGetPickOf(cardFile) {
    return String(asTableGet(cardFile)[AS_PICK_URL] || '');
}

function asGetPick() {
