}

function asGetUploadedOf(cardFile) {
    const list = asTableGet(cardFile)[AS_UPLOADED];
    return Array.isArray(list) ? asNormalize(list) : [];
}

function asGetUploaded() {
    return asGetUploadedOf(asAvatarFile());
}

function asSetUploaded(list) {
    const card = asAvatarFile();
    if (!card) return;
    asTableSet(card, { [AS_UPLOADED]: (list || []).map(x => ({ [AS_ITEM_NAME]: x.name, [AS_ITEM_URL]: x.url })) });
}

function asRenameUploaded(url, name) {
    const list = asGetUploaded().map(x => (x.url === url ? { name: String(name || '').trim() || asFileName(x.url), url: x.url } : x));
    asSetUploaded(list);
}

const AS_DB_NAME = '卡面替换';
const AS_DB_STORE = 'img';
let asDbPromise = null;

function asDb() {
    if (asDbPromise) return asDbPromise;
    asDbPromise = new Promise(resolve => {
        let settled = false;
        const done = v => { if (settled) return; settled = true; resolve(v); };
        try {
            const idb = asWin().indexedDB || window.indexedDB;
            if (!idb) { done(null); return; }
            const req = idb.open(AS_DB_NAME, 1);
            req.onupgradeneeded = () => {
                const db = req.result;
                if (!db.objectStoreNames.contains(AS_DB_STORE)) db.createObjectStore(AS_DB_STORE);
            };
            req.onsuccess = () => done(req.result);
            req.onerror = () => done(null);
            req.onblocked = () => done(null);
        } catch (e) {
            done(null);
        }
        setTimeout(() => done(null), 3000);
    });
    return asDbPromise;
}

function asDbDo(mode, fn, wantResult) {
    return asDb().then(db => {
        if (!db) return wantResult ? null : false;
        return new Promise(resolve => {
            try {
                const tx = db.transaction(AS_DB_STORE, mode);
                const store = tx.objectStore(AS_DB_STORE);
                const req = fn(store);
                if (wantResult) {
                    if (req) {
                        req.onsuccess = () => resolve(req.result);
                        req.onerror = () => resolve(null);
                    } else {
                        tx.oncomplete = () => resolve(null);
                        tx.onerror = () => resolve(null);
                    }
                } else {
                    tx.oncomplete = () => resolve(true);
                    tx.onerror = () => resolve(false);
                    tx.onabort = () => resolve(false);
                }
            } catch (e) {
                resolve(wantResult ? null : false);
            }
        });
    });
}

function asDbGet(k) { return asDbDo('readonly', s => s.get(k), true); }
function asDbSet(k, v) { return asDbDo('readwrite', s => s.put(v, k), false); }
function asDbDel(k) { return asDbDo('readwrite', s => s.delete(k), false); }

function asKey(k) {
    return 'img_' + k;
}

function asRef(k) {
    return 'upload:' + k;
}

function asNewKey() {
    return 'u' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

async function asResolve(ref) {
    if (!ref) return '';
    if (ref.indexOf('upload:') !== 0) return ref;
    const data = await asDbGet(asKey(ref.slice(7)));
    return typeof data === 'string' ? data : '';
}

async function asSrcFor(ref) {
    const resolved = await asResolve(ref);
    if (resolved) return resolved;
    const first = asCardList()[0];
    return first ? first.url : '';
}

async function asSrcStrict(ref) {
    if (!ref) return '';
    return await asResolve(ref);
}

function asBust(url) {
    if (!url || url.indexOf('http') !== 0) return url;
    return url + (url.indexOf('?') >= 0 ? '&' : '?') + '_as=1';
}

function asThumbUrl(cardFile) {
    if (!cardFile) return '';
    return '/thumbnail?type=avatar&file=' + encodeURIComponent(cardFile);
}

function asWithTimeout(p, ms, fallback) {
    return new Promise(resolve => {
        let settled = false;
        const done = v => { if (settled) return; settled = true; resolve(v); };
        setTimeout(() => done(fallback), ms);
        Promise.resolve(p).then(v => done(v), () => done(fallback));
    });
}

const asThumbCache = new Map();

function asMakeThumb(src) {
    if (!src) return Promise.resolve('');
    if (src.indexOf('data:') !== 0) return Promise.resolve(src);   // 外链本来就小，让浏览器自己缩
    if (asThumbCache.has(src)) return Promise.resolve(asThumbCache.get(src));
    return new Promise(resolve => {
        const img = new Image();
        img.onload = () => {
            try {
                const side = 240;
                const cv = asDoc().createElement('canvas');
                const w = img.naturalWidth || side;
                const h = img.naturalHeight || side;
                const scale = Math.min(1, side / Math.max(w, h));
                cv.width = Math.max(1, Math.round(w * scale));
                cv.height = Math.max(1, Math.round(h * scale));
                cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height);
                const out = cv.toDataURL('image/jpeg', 0.82);
                asThumbCache.set(src, out);
                resolve(out);
            } catch (e) {
                resolve(src);   // canvas 被跨域污染之类，退回原图，能用就行
            }
        };
        img.onerror = () => resolve(src);
        img.src = src;
    });
}

function asSetSrc(el, url) {
    if (!url) return;
    const img = el.tagName === 'IMG' ? el : el.querySelector('img');
    if (!img) return;
    img.dataset.asSrc = url;
    const want = asBust(url);
    if (img.getAttribute('src') === want) return;   // 已经是这张了，不重复写，避免观察器自触发
    img.src = want;
}

function asSetZoomedImg(img, url) {
    const want = asBust(url);
    if (img.getAttribute('src') !== want) img.src = want;
    img.setAttribute('data-izoomify-url', want);
    img.dataset.asSrc = url;
}

function asEnsureHosts() {
    const doc = asDoc();
    const oldScroll = doc.querySelector('#as_panel .as_scroll');
    const oldTabs = doc.querySelector('#as_panel .as_tabs');

    let scroll = oldScroll;
    if (!scroll) {
        scroll = asEl('div', 'as_scroll');
        asScrollHost.appendChild(scroll);
    } else if (scroll.parentNode !== asScrollHost) {
        asScrollHost.appendChild(scroll);
    }

    let tabs = oldTabs;
    if (!tabs) {
        tabs = asEl('div', 'as_tabs');
        asTabsHost.appendChild(tabs);
    } else if (tabs.parentNode !== asTabsHost) {
        asTabsHost.appendChild(tabs);
    }

    if (!scroll.querySelector('.as_grid')) scroll.appendChild(asEl('div', 'as_grid'));

    if (!asListHook && asListHookTarget) {
        asListHook = true;
        if (typeof window.parent.MutationObserver === 'function') {
            const target = asListHookTarget;
            const mo = new window.parent.MutationObserver(() => {
                if (asGridBusy) return;
                asEnsureHosts();
                asRenderGrid();
            });
            mo.observe(target.parentNode || target, { childList: true });
        }
    }
    if (!asSearchHook) {
        asSearchHook = true;
        const bar = doc.getElementById('character_search_bar');
        if (bar) bar.addEventListener('input', () => { if (!asGridBusy) asRenderGrid(); });
        else asSearchHook = false;   // 还没渲染出来，下次再挂
    }
}

function asAskRedraw() {
    const doc = asDoc();
    let id = null;
    try { id = SillyTavern.getContext().characterId; } catch (e) { }
    if (id === undefined || id === null || id === '') return false;

    const panel = doc.getElementById('right-nav-panel');
    const list = panel && panel.querySelector('#rm_print_characters_block');
    const item = list && list.querySelector('.character_select[data-chid="' + Number(id) + '"]');
    if (!item) return false;

    let fired = false;
    const onClick = ev => {
        ev.stopImmediatePropagation();
        fired = true;
    };
    item.addEventListener('click', onClick, true);
    try { item.click(); } catch (e) { }
    item.removeEventListener('click', onClick, true);
    return fired;
}

function asApplyZoomed(doc, url) {
    doc.querySelectorAll('.zoomed_avatar .zoomed_avatar_img, img.zoomed_avatar_img').forEach(img => {
        if (img.closest('#zoomed_avatar_template')) return;
        asSetZoomedImg(img, url);
    });
}

async function asApplyList(doc, card) {
    let list = null;
    let curId = null;
    try {
        const ctx = SillyTavern.getContext();
        list = ctx.characters;
        curId = ctx.characterId;
    } catch (e) { }
    const name2 = asCharName();

    const jobs = [];
    doc.querySelectorAll('.character_select').forEach(node => {
        const raw = node.getAttribute('data-chid') ?? node.getAttribute('chid');
        if (raw === null || raw === '') return;
        const id = Number(raw);
        let mine = false;
        let cardFile = '';

        if (curId !== undefined && curId !== null && curId !== '' && id === Number(curId)) {
            mine = true;
            cardFile = card;
        } else {
            const entry = list && list[id];
            if (entry && (!card || entry.avatar === card)) {
                mine = true;
                cardFile = entry.avatar || card;
            }
        }
        if (!mine && name2) {
            const shown = (node.querySelector('.ch_name')?.textContent || '').trim();
            if (shown && shown === name2) {
                mine = true;
                cardFile = card;
            }
        }
        if (!mine) return;

        const ref = asGetPickOf(cardFile);
        if (!ref) return;
        if (node.dataset.asRef === ref) return;   // 已经是这张了，别重复解析
        jobs.push(
            asSrcStrict(ref).then(src => {
                if (!src) return;
                node.dataset.asRef = ref;
                node.querySelectorAll('.avatar img, img').forEach(img => asSetSrc(img, src));
            }).catch(() => { }),
        );
    });
    await Promise.all(jobs);
}

async function asApply() {
    const ref = asGetPick();
    if (!ref) return false;
    const url = await asSrcFor(ref);
    if (!url) return false;

    asApplying = true;
    let sawMine = false;
    try {
        const doc = asDoc();
        const card = asAvatarFile();

        asApplyZoomed(doc, url);

        const asBox = doc.getElementById('avatar_div');
        const asPrev = asBox && (asBox.querySelector('#avatar_load_preview') || asBox.querySelector('img'));
        if (asPrev) asSetSrc(asPrev, url);
        if (asPrev && asPrev.getAttribute('src') === asBust(url)) sawMine = true;

        await asApplyList(doc, card);

        doc.querySelectorAll('#chat .mes .avatar img').forEach(img => asSetSrc(img, url));

        asEnsureHosts();
    } finally {
        setTimeout(() => {
            asApplying = false;
            if (asDirty) { asDirty = false; asApply(); }
        }, 0);
    }
    return sawMine;
}

function asRestoreCurrent() {
    const doc = asDoc();
    const card = asAvatarFile();
    const orig = asThumbUrl(card);

    asAskRedraw();

    if (orig) {
        const box = doc.getElementById('avatar_div');
        const prev = box && (box.querySelector('#avatar_load_preview') || box.querySelector('img'));
        if (prev) {
            prev.removeAttribute('data-as-src');
            if (prev.getAttribute('src') !== orig) prev.setAttribute('src', orig);
        }
        doc.querySelectorAll('#chat .mes .avatar img').forEach(img => {
            img.removeAttribute('data-as-src');
            if (img.getAttribute('src') !== orig) img.setAttribute('src', orig);
        });
    }

    const name2 = asCharName();
    let list = null;
    let curId = null;
    try {
        const ctx = SillyTavern.getContext();
        list = ctx.characters;
        curId = ctx.characterId;
    } catch (e) { }

    doc.querySelectorAll('.character_select').forEach(node => {
        if (!node.dataset.asRef) return;   // 没被我动过，别管
        const raw = node.getAttribute('data-chid') ?? node.getAttribute('chid');
        if (raw === null || raw === '') return;
        const id = Number(raw);
        let mine = false;
        let cardFile = card;
        if (curId !== undefined && curId !== null && curId !== '' && id === Number(curId)) {
            mine = true;
        } else {
            const entry = list && list[id];
            if (entry && (!card || entry.avatar === card)) { mine = true; cardFile = entry.avatar || card; }
        }
        if (!mine && name2) {
            const shown = (node.querySelector('.ch_name')?.textContent || '').trim();
            if (shown && shown === name2) mine = true;
        }
        if (!mine) return;
        const back = asThumbUrl(cardFile);
        delete node.dataset.asRef;
        node.querySelectorAll('.avatar img, img').forEach(img => {
            img.removeAttribute('data-as-src');
            if (back && img.getAttribute('src') !== back) img.setAttribute('src', back);
        });
    });

    doc.querySelectorAll('.zoomed_avatar .zoomed_avatar_img, img.zoomed_avatar_img').forEach(img => {
        if (img.closest('#zoomed_avatar_template')) return;   // 隐藏样板，别动
        img.removeAttribute('data-as-src');
        const full = card ? ('/characters/' + encodeURIComponent(card)) : '';
        if (full) {
            if (img.getAttribute('src') !== full) img.setAttribute('src', full);
            img.setAttribute('data-izoomify-url', full);
        }
    });
}

function asKick() {
    if (asRetryTimer) clearInterval(asRetryTimer);
    const deadline = Date.now() + 30000;
    let busy = false;
    const step = async () => {
        if (busy) return;
        busy = true;
        let ok = false;
        try { ok = await asApply(); } catch (e) { }
        busy = false;
        if (ok || Date.now() > deadline) {
            clearInterval(asRetryTimer);
            asRetryTimer = null;
        }
    };
    step();
    asRetryTimer = setInterval(step, 200);
}

function asWatch() {
    const doc = asDoc();
    const target = doc.body;
    if (!target) {
        setTimeout(() => asWatch(), 100);
        return;
    }
    if (asObserver && asObserverTarget === target) return;
    asUnwatch();
    asObserverTarget = target;
    asObserver = new MutationObserver(muts => {
        if (asApplying) { asDirty = true; return; }
        let hit = false;
        for (const m of muts) {
            if (m.type === 'attributes') {
                const t = m.target;
                if (t && (t.id === 'avatar_load_preview' || t.closest?.('#avatar_div') || t.classList?.contains('zoomed_avatar_img'))) {
                    hit = true; break;
                }
                if (t && t.tagName === 'IMG' && t.closest?.('.character_select')) {
                    hit = true; break;
                }
                continue;
            }
            for (const n of m.addedNodes) {
                if (n.nodeType !== 1) continue;
                if (n.matches?.('.zoomed_avatar, .character_select') ||
                    n.querySelector?.('.zoomed_avatar_img, .character_select')) {
                    hit = true; break;
                }
            }
            if (hit) break;
        }
        if (!hit) return;
        if (asTimer) clearTimeout(asTimer);
        asTimer = setTimeout(() => { asTimer = null; asApply(); }, 0);
    });
    asObserver.observe(target, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ['src'],
    });
}

function asUnwatch() {
    if (asObserver) asObserver.disconnect();
    if (asTimer) { clearTimeout(asTimer); asTimer = null; }
    asObserver = null;
    asObserverTarget = null;
}

