        'border:1px solid var(--SmartThemeBorderColor,#555);animation:as_pop .18s cubic-bezier(.2,.9,.3,1.2)}',
        '#as_namemask .as_ntitle{font-size:14px;font-weight:600;margin-bottom:10px}',
        '#as_namemask input{width:100%;box-sizing:border-box;padding:8px 10px;border-radius:8px;font-size:14px;',
        'border:1px solid var(--SmartThemeBorderColor,#555);background:rgba(0,0,0,.22);color:inherit;outline:none}',
        '#as_namemask input:focus{border-color:var(--SmartThemeQuoteColor,#9c6)}',
