        '#as_namemask button{border-radius:8px;padding:6px 14px;cursor:pointer;font-size:13px;transition:.15s;',
        'border:1px solid var(--SmartThemeBorderColor,#555);background:transparent;color:inherit}',
        '#as_namemask button:hover{border-color:var(--SmartThemeQuoteColor,#9c6)}',
        '#as_namemask button.as_main{background:var(--SmartThemeQuoteColor,#9c6);color:#111;border-color:transparent;font-weight:600}',
        '#as_namemask .as_nhint{font-size:11px;opacity:.5;margin-top:6px}',
    ].join('');
    doc.head.appendChild(style);
}

function asEl(tag, cls, text) {
    const el = asDoc().createElement(tag);
    if (cls) el.className = cls;
    if (text !== undefined) el.textContent = text;
    return el;
}

/* ================= 移动端尺寸兼容 =================
 * 部分移动内核会把 html 高度算成 0，此时 fixed + inset:0 的容器解析高度为 0，
 * 内容被居中到最顶端（表现为「弹层贴顶」）。以下用 JS 量视口写内联像素宽高，
 * 并监听 resize 跟随；桌面端量出的值与视口一致，行为不变。 */
let asFitHooked = false;
function asApplyFit(el) {
    if (!el) return;
    const doc = asDoc();
    const w = doc.documentElement.clientWidth || doc.defaultView.innerWidth || 0;
    const h = doc.documentElement.clientHeight || doc.defaultView.innerHeight || 0;
    el.style.width = w + 'px';
    el.style.height = h + 'px';
}
function asHookFit() {
    if (asFitHooked) return;
    asFitHooked = true;
    asDoc().defaultView.addEventListener('resize', () => {
        const doc = asDoc();
        [AS_PANEL_ID, AS_VIEW_ID, AS_NAME_ID].forEach(id => asApplyFit(doc.getElementById(id)));
    });
}

/* ================= 改名弹窗 ================= */

function asAskName(title, init) {
    return new Promise(resolve => {
        const doc = asDoc();
        asStyle();
        doc.getElementById(AS_NAME_ID)?.remove();

        const mask = asEl('div');
        mask.id = AS_NAME_ID;

        const box = asEl('div', 'as_nbox');
        box.appendChild(asEl('div', 'as_ntitle', title));

        const inp = doc.createElement('input');
        inp.type = 'text';
        inp.value = init || '';
        box.appendChild(inp);
        box.appendChild(asEl('div', 'as_nhint', '留空则用原文件名'));

        const row = asEl('div', 'as_nrow');
        const ok = asEl('button', 'as_main', '确定');
        const no = asEl('button', '', '取消');
        row.append(no, ok);
        box.appendChild(row);
        mask.appendChild(box);

        let done = false;
        const finish = v => {
            if (done) return;
            done = true;
            mask.remove();
            resolve(v);
        };

        ok.addEventListener('click', () => finish(inp.value));
        no.addEventListener('click', () => finish(null));
        mask.addEventListener('click', ev => { if (ev.target === mask) finish(null); });
        inp.addEventListener('keydown', ev => {
            if (ev.key === 'Enter') { ev.preventDefault(); finish(inp.value); }
            if (ev.key === 'Escape') { ev.preventDefault(); finish(null); }
        });

        doc.body.appendChild(mask);
        asHookFit();
        asApplyFit(mask);
        setTimeout(() => { inp.focus(); inp.select(); }, 30);
    });
}

async function asAskNames(items) {
    const out = [];
    for (let i = 0; i < items.length; i++) {
        const head = items.length > 1 ? '（' + (i + 1) + '/' + items.length + '）' : '';
        const v = await asAskName('给这张图起个名字' + head, items[i].name);
        if (v === null) {
            if (items.length > 1 && i > 0) toastr.info('已保留前 ' + i + ' 张');
            break;
        }
        out.push({ name: String(v).trim() || items[i].name, url: items[i].url });
    }
    return out;
}

/* ================= 大图预览 ================= */

async function asClearAndRestore() {
    asSetPick('');
    asRestoreCurrent();
    await asRenderGrid();
}

async function asPreview(item, isLocal, onChanged) {
    const doc = asDoc();
    asStyle();
    doc.getElementById(AS_VIEW_ID)?.remove();

    const src = await asSrcFor(item.url);

    const view = asEl('div');
    view.id = AS_VIEW_ID;

    const box = asEl('div', 'as_vbox');

    const img = doc.createElement('img');
    img.className = 'as_vimg';
    img.src = src;
    img.alt = item.name;
    if (!src) img.style.minWidth = '200px';

    const meta = asEl('div', 'as_vmeta');
    meta.appendChild(asEl('span', '', item.name));
    meta.appendChild(asEl('span', 'as_vtag', isLocal ? '本地' : '官方'));

    const info = isLocal ? asEl('div', 'as_vinfo', '存在本机浏览器里，只有你自己看得到') : null;

    const row = asEl('div', 'as_vrow');
    const okBtn = asEl('button', 'as_main', '应用这张');
    const renameBtn = isLocal ? asEl('button', '', '改名') : null;
    const delBtn = isLocal ? asEl('button', '', '删除') : null;
    const noBtn = asEl('button', '', '取消');
    if (renameBtn) row.appendChild(renameBtn);
    if (delBtn) row.appendChild(delBtn);
    row.append(noBtn, okBtn);

    box.append(img, meta, ...(info ? [info] : []), row);
    view.appendChild(box);

    const close = () => view.remove();
    view.addEventListener('click', ev => { if (ev.target === view) close(); });
    noBtn.addEventListener('click', close);

    okBtn.addEventListener('click', () => {
        asSetPick(item.url);
        close();
        toastr.success('已换上「' + asClip(item.name, 10) + '」');
        if (onChanged) onChanged();
        asApply();
    });

    if (renameBtn) {
        renameBtn.addEventListener('click', async () => {
            const v = await asAskName('改名', item.name);
            if (v === null) return;
            const name = String(v).trim() || asFileName(item.url);
            asRenameUploaded(item.url, name);
            item.name = name;
            meta.firstChild.textContent = name;
            img.alt = name;
            if (onChanged) onChanged();
        });
    }

    if (delBtn) {
        delBtn.addEventListener('click', async () => {
            const wasPicked = asGetPick() === item.url;
            await asDbDel(asKey(item.url.slice(7)));
            asSetUploaded(asGetUploaded().filter(x => x.url !== item.url));
            close();
            toastr.info('已删除');
            if (wasPicked) {
                await asClearAndRestore();
            } else {
                if (onChanged) onChanged();
            }
        });
    }

    doc.body.appendChild(view);
    asHookFit();
    asApplyFit(view);
}

/* ================= 网格 ================= */

function asTabList() {
    return [
        { key: 'all', label: '全部' },
        { key: 'official', label: '官方' },
        { key: 'local', label: '本地' },
    ];
}

async function asRenderGrid() {
    const doc = asDoc();
    const scroll = doc.querySelector('#as_panel .as_scroll');
    const tabs = doc.querySelector('#as_panel .as_tabs');
    if (!scroll) return;

    asGridBusy = true;
    try {
        await asRenderGridBody(doc, scroll, tabs);
    } finally {
        setTimeout(() => { asGridBusy = false; }, 0);
    }
}

async function asRenderGridBody(doc, scroll, tabs) {
    const official = asCardList();
    const uploaded = asGetUploaded();
    const picked = asGetPick();

    let list;
    if (asTab === 'official') list = official.map(x => ({ item: x, local: false }));
    else if (asTab === 'local') list = uploaded.map(x => ({ item: x, local: true }));
    else list = official.map(x => ({ item: x, local: false })).concat(uploaded.map(x => ({ item: x, local: true })));

    if (tabs) {
        tabs.innerHTML = '';
        const counts = { all: official.length + uploaded.length, official: official.length, local: uploaded.length };
        for (const t of asTabList()) {
            const b = asEl('div', 'as_tab' + (asTab === t.key ? ' as_cur' : ''), t.label);
            b.appendChild(asEl('i', '', String(counts[t.key])));
            b.addEventListener('click', () => { asTab = t.key; asRenderGrid(); });
            tabs.appendChild(b);
        }
    }

    scroll.innerHTML = '';
    const grid = asEl('div', 'as_grid');
    scroll.appendChild(grid);

    if (!list.length) {
        grid.appendChild(asEl('div', 'as_empty', asTab === 'local'
            ? '还没有自己的图。点右下角「上传本地图片」加几张。'
            : '这张卡没有卡面。'));
    }

    const cards = await Promise.all(list.map(async ({ item, local }) => {
        let full = '';
        let thumb = '';
        try {
            full = await asWithTimeout(asSrcFor(item.url), 4000, '');
            thumb = await asWithTimeout(asMakeThumb(full), 4000, '');
        } catch (e) {
            full = '';
            thumb = '';
        }
        return { item, local, full, thumb };
    }));

    for (const { item, local, full, thumb } of cards) {
        const cell = asEl('div', 'as_cell');
        if (picked && picked === item.url) cell.classList.add('as_on');
        if (!full) cell.classList.add('as_bad');

        const img = doc.createElement('img');
        img.alt = item.name;
        img.src = thumb;
        cell.appendChild(img);

        const cap = asEl('span', 'as_cap', item.name);
        cell.appendChild(cap);
        cell.title = asClip(item.name, 20) + '\n' + (local ? '本地图片' : '官方')
            + (full ? '' : '\n（这张读不出来，可能已损坏）');

        if (picked && picked === item.url) cell.appendChild(asEl('i', 'as_ok', '✓'));

        if (local) {
            const acts = asEl('div', 'as_acts');
            const pen = asEl('i', '', '✎');
            pen.title = '改名';
            pen.addEventListener('click', async ev => {
                ev.stopPropagation();
                const v = await asAskName('改名', item.name);
                if (v === null) return;
                asRenameUploaded(item.url, String(v).trim() || asFileName(item.url));
                await asRenderGrid();
            });
            const del = asEl('i', '', '✕');
            del.title = '删除这张图';
            del.addEventListener('click', async ev => {
                ev.stopPropagation();
                const wasPicked = asGetPick() === item.url;
                await asDbDel(asKey(item.url.slice(7)));
                asSetUploaded(asGetUploaded().filter(x => x.url !== item.url));
                if (wasPicked) {
                    await asClearAndRestore();
                } else {
                    await asRenderGrid();
                }
            });
            acts.append(pen, del);
            cell.appendChild(acts);
        }

        cell.addEventListener('click', () => asPreview(item, local, () => asRenderGrid()));

        grid.appendChild(cell);
    }
}

/* ================= 面板 ================= */

async function asOpen() {
    const doc = asDoc();
    if (doc.getElementById(AS_PANEL_ID)) return;

    asStyle();

    const panel = asEl('div');
    panel.id = AS_PANEL_ID;

    const box = asEl('div', 'as_box');

    const head = asEl('div', 'as_head');
    head.appendChild(asEl('div', 'as_title', '更换卡面'));
    head.appendChild(asEl('div', 'as_who', asCharName()));
    const x = asEl('div', 'as_x', '✕');
    x.title = '关闭';
    x.addEventListener('click', () => asClose());
    head.appendChild(x);
    box.appendChild(head);

    const tabs = asEl('div', 'as_tabs');
    box.appendChild(tabs);

    const scroll = asEl('div', 'as_scroll');
    box.appendChild(scroll);

    const foot = asEl('div', 'as_foot');

    const file = doc.createElement('input');
    file.type = 'file';
    file.accept = 'image/*';
    file.multiple = true;
    file.style.display = 'none';

    const upBtn = asEl('button', 'as_main', '上传本地图片');
    upBtn.addEventListener('click', () => file.click());

    const resetBtn = asEl('button', '', '恢复原卡面');
    resetBtn.addEventListener('click', async () => {
        asSetPick('');
        asRestoreCurrent();
        await asRenderGrid();
        toastr.info('已恢复原卡面');
    });

    const closeBtn = asEl('button', '', '关闭');
    closeBtn.addEventListener('click', () => asClose());

    foot.append(upBtn, resetBtn, asEl('span', 'as_gap'), closeBtn);

    file.addEventListener('change', async () => {
        const files = Array.from(file.files || []);
        file.value = '';
        if (!files.length) return;

        const db = await asDb();
        if (!db) {
            toastr.error('本机存储不可用');
            return;
        }

        const list = asGetUploaded().slice();
        const fresh = [];

        for (const f of files) {
            const data = await asReadFile(f);
            if (!data) continue;
            const k = asNewKey();
            const ok = await asDbSet(asKey(k), data);
            if (!ok) { toastr.error(f.name + ' 存不进去'); continue; }
            fresh.push({ name: asFileName(f.name) || f.name, url: asRef(k) });
        }

        if (!fresh.length) return;

        const named = await asAskNames(fresh);
        const rest = named.length ? named : fresh;

        asSetUploaded(list.concat(rest));

        asTab = 'local';
        await asRenderGrid();
        if (named.length !== fresh.length) toastr.info('已存入 ' + rest.length + ' 张');
    });

    box.appendChild(foot);
    box.appendChild(file);
    panel.appendChild(box);

    panel.addEventListener('click', ev => {
        if (ev.target === panel) asClose();
    });

    doc.body.appendChild(panel);
    asHookFit();
    asApplyFit(panel);

    asScrollHost = scroll.parentNode;
    asTabsHost = tabs.parentNode;
    asListHookTarget = doc.getElementById('rm_print_characters_block');
    asListHook = false;
    asSearchHook = false;
    asEnsureHosts();

    await asRenderGrid();
}

function asClose() {
    const doc = asDoc();
    doc.getElementById(AS_PANEL_ID)?.remove();
    doc.getElementById(AS_VIEW_ID)?.remove();
    doc.getElementById(AS_NAME_ID)?.remove();
}

function asReadFile(f) {
    return new Promise(resolve => {
        const r = new FileReader();
        r.onload = () => resolve(typeof r.result === 'string' ? r.result : '');
        r.onerror = () => resolve('');
        r.readAsDataURL(f);
    });
}

/* ================= 启动 ================= */

$(async () => {
    appendInexistentScriptButtons([{ name: AS_BUTTON, visible: true }]);
    eventOn(getButtonEvent(AS_BUTTON), () => asOpen());

    const refresh = () => setTimeout(() => asApply(), 80);

    for (const name of ['CHAT_CHANGED', 'CHARACTER_MESSAGE_RENDERED', 'USER_MESSAGE_RENDERED', 'MESSAGE_SWIPED']) {
        const t = tavern_events[name];
        if (t) eventOn(t, refresh);
    }

    eventOn(tavern_events.CHAT_CHANGED, () => {
        setTimeout(() => { asApply(); asWatch(); }, 150);
    });

    const pageLoaded = () => {
        for (const ms of [0, 120, 400, 900]) {
            setTimeout(() => asApply(), ms);
        }
    };
    for (const name of ['CHARACTER_PAGE_LOADED', 'CHARACTER_EDITOR_OPENED']) {
        const t = tavern_events[name];
        if (t) eventOn(t, pageLoaded);
    }

    asKick();
    asWatch();

    $(window).on('pagehide', () => {
        asUnwatch();
        if (asRetryTimer) { clearInterval(asRetryTimer); asRetryTimer = null; }
        asDirty = false;
    });
});
